        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('12051111-0000-4000-8000-000000000001', 'What shocking order from Berlin did M. Hamel announce to his Alsace classroom?', '{"A":"School was relocating","B":"Only German would be taught in the schools of Alsace and Lorraine from tomorrow","C":"Examinations were cancelled","D":"M. Hamel was promoted"}'::jsonb, 'B', 'MCQ', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 1, 'Prussian annexers banned teaching French.', NULL, NULL, 'Prussian annexers banned teaching French.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000002', 'Why did village elders like Old Hauser sit quietly on the back benches during "The Last Lesson"?', '{"A":"To supervise kids","B":"To show gratitude for M. Hamel''s 40 years of faithful service and mourn losing their mother tongue","C":"Wait for mayor","D":"Avoid farm work"}'::jsonb, 'B', 'MCQ', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 1, 'Collective remorse for neglecting French earlier.', NULL, NULL, 'Collective remorse for neglecting French earlier.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000003', 'What did Saheb-e-Alam mean by his name, contrasting with his barefoot life in Seemapuri?', '{"A":"Friend of poor","B":"\"Lord of the Universe\" — ironical against scavenging garbage heaps barefoot","C":"Master of gold","D":"King of rivers"}'::jsonb, 'B', 'MCQ', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 1, 'Situational irony between grand name and poverty.', NULL, NULL, 'Situational irony between grand name and poverty.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000004', 'Why did Mukesh''s family in Firozabad NOT form a cooperative against middlemen and police?', '{"A":"No time","B":"Fear of being hauled up, beaten, and jailed by a vicious nexus of sahukars, middlemen, policemen, and politicians","C":"Lack of glass","D":"Good wages already"}'::jsonb, 'B', 'MCQ', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 1, 'Lack of bold leadership keeps bangle-makers trapped.', NULL, NULL, 'Lack of bold leadership keeps bangle-makers trapped.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000005', 'How did Saheb feel after giving up ragpicking to work at a tea stall earning ₹800 and meals?', '{"A":"Completely happy","B":"Less carefree — the steel canister seemed heavier than his light plastic ragpicker bag because he was no longer his own master","C":"Wealthy","D":"Proud"}'::jsonb, 'B', 'MCQ', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 1, 'Lost his childhood freedom and autonomy.', NULL, NULL, 'Lost his childhood freedom and autonomy.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000006', 'Why did M. Hamel call the French language the key to their prison when people are enslaved?', '{"A":"It unlocks doors","B":"Holding fast to one''s native language preserves cultural identity, unity, and resistance against conquerors","C":"It is easy","D":"Dictionaries help"}'::jsonb, 'B', 'MCQ', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 1, 'Mother tongue sustains freedom spirit.', NULL, NULL, 'Mother tongue sustains freedom spirit.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000007', 'Why did Franz fear going to school that morning, yet what strange things surprised him inside?', NULL, NULL, 'VSA', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 2, 'He was late and hadn''t prepared participles; instead of bustle, Friday-like Sunday quiet reigned, M. Hamel wore his special green coat, and village elders sat silently on back benches.', '2 × 1M', NULL, 'He was late and hadn''t prepared participles; instead of bustle, Friday-like Sunday quiet reigned, M. Hamel wore his special green coat, and village elders sat silently on back benches.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000008', 'Contrast Saheb''s perception of garbage vs the elders'' perception in Seemapuri.', NULL, NULL, 'VSA', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 2, 'For elders, garbage is daily bread ("a roof over their heads, even if leaking"); for children like Saheb, it is wrapped in wonder — hoping to find a coin or ₹10 note.', '1M each', NULL, 'For elders, garbage is daily bread ("a roof over their heads, even if leaking"); for children like Saheb, it is wrapped in wonder — hoping to find a coin or ₹10 note.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000009', '(i) What did M. Hamel write on the blackboard as the church clock struck twelve? (ii) Why could he not speak at the end? (iii) Mention two excuses parents and M. Hamel himself gave for children skipping French earlier. (iv) One word for linguistic imposition over conquered peoples.', NULL, NULL, 'CASE', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 4, '(i) "Vive La France!" (Long Live France!). (ii) Overwhelming patriotic grief choked his throat. (iii) Parents sent kids to mills/farms for extra money; Hamel sent kids to water flowers or gave holiday when going fishing. (iv) Linguistic chauvinism.', '4 × 1M = 4M', 'Context: Leaning his head against the classroom wall at noon as Prussian soldiers'' trumpets sounded outside, M. Hamel picked up chalk and wrote in giant letters before dismissing school.', '(i) "Vive La France!" (Long Live France!). (ii) Overwhelming patriotic grief choked his throat. (iii) Parents sent kids to mills/farms for extra money; Hamel sent kids to water flowers or gave holiday when going fishing. (iv) Linguistic chauvinism.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000000a', 'Compare Mukesh''s daring dream ("I want to be a motor mechanic") against the fatalistic acceptance of his grandmother ("karam" destiny).', NULL, NULL, 'CASE', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 4, 'Grandmother believes caste-bound bangle-making is unbreakable god-given lineage despite blinding furnace dust; Mukesh refuses hereditary blindness and dares walk miles to learn car repair — a spark of determination.', 'Grandmother fatalism (2M) + Mukesh resolve (2M)', NULL, 'Grandmother believes caste-bound bangle-making is unbreakable god-given lineage despite blinding furnace dust; Mukesh refuses hereditary blindness and dares walk miles to learn car repair — a spark of determination.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000000b', 'Compare the theme of Deprivation & Lost Autonomy in "The Last Lesson" (linguistic subjugation) and "Lost Spring" (generational poverty & child labour).', NULL, NULL, 'LA', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 5, 'Daudet exposes how citizens wake up to the priceless value of mother tongue only when Berlin bans French in Alsace. Anees Jung exposes silent socio-economic bondage in Seemapuri (garbage survival trading freedom for a tea canister) and Firozabad (inherited glass-furnace blindness) — urging structural empathy and education.', 'Last Lesson (2.5M) + Lost Spring (2.5M)', NULL, 'Daudet exposes how citizens wake up to the priceless value of mother tongue only when Berlin bans French in Alsace. Anees Jung exposes silent socio-economic bondage in Seemapuri (garbage survival trading freedom for a tea canister) and Firozabad (inherited glass-furnace blindness) — urging structural empathy and education.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000000c', 'FLAMINGO PROSE EXTRACT (6 × 1M):
(i) Who does "I" refer to in this Seemapuri encounter? (ii) Why do mothers describe green Dhaka fields as "storm-swept"? (iii) What do ragpickers prioritize more than citizenship identity (ration cards vs transit permits)? (iv) Meaning of "perpetual state of poverty". (v) Why do barefoot boys excuse not wearing chappals as "tradition"? (vi) Name the author of "Lost Spring".', NULL, NULL, 'CASE', 'English Core', 'The Last Lesson & Lost Spring (Flamingo)', 6, '(i) Narrator Anees Jung. (ii) Cyclones repeatedly swept away ancestral crops & homes near Dhaka rivers forcing migration. (iii) Survival food over formal identity — ration cards get grain for votes while tents stand wherever food appears. (iv) Unending continuous poverty. (v) Masks utter lack of money to buy shoes. (vi) Anees Jung.', '6 × 1M = 6M', '"Sometimes I find a rupee in the garbage," Saheb answers cheerfully when asked why he scrounges dumps. Having left green Bangladeshi riverfields swept away by storms long ago, ten thousand ragpickers live in mud structures in Seemapuri where survival food matters more than identity.', '(i) Narrator Anees Jung. (ii) Cyclones repeatedly swept away ancestral crops & homes near Dhaka rivers forcing migration. (iii) Survival food over formal identity — ration cards get grain for votes while tents stand wherever food appears. (iv) Unending continuous poverty. (v) Masks utter lack of money to buy shoes. (vi) Anees Jung.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000000d', 'At what age did the misadventure at the YMCA swimming pool nearly drown William Douglas?', '{"A":"Three years","B":"Ten or eleven years old (when an 18-year-old bruiser tossed him into 9-foot deep end)","C":"Fifteen","D":"Twenty"}'::jsonb, 'B', 'MCQ', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 1, 'Following earlier California beach wave knock-down at age 3–4.', NULL, NULL, 'Following earlier California beach wave knock-down at age 3–4.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000000e', 'What strategy did Douglas plan while sinking the first two times toward the tiled pool bottom?', '{"A":"Float on back","B":"Make a giant spring/jump upward upon touching bottom, pop to surface like a cork, lie flat and paddle","C":"Scream underwater","D":"Hold breath for 10 mins"}'::jsonb, 'B', 'MCQ', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 1, 'Stark terror paralysed limbs once upward jump brought only yellow water.', NULL, NULL, 'Stark terror paralysed limbs once upward jump brought only yellow water.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000000f', 'Why did the lonely rattrap peddler laugh imagining the whole world as a giant rattrap?', '{"A":"He loved cheese","B":"The world offers riches, shelter, and food merely as tempting bait to snap shut around anyone who touches them","C":"He sold many traps","D":"He read novels"}'::jsonb, 'B', 'MCQ', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 1, 'Cynical metaphor born of harsh wandering.', NULL, NULL, 'Cynical metaphor born of harsh wandering.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000010', 'How did the crofter treat the peddler and how did the peddler repay him?', '{"A":"Chased him out","B":"Fed him porridge, played mjolis cards, showed 30 kronor in window pouch — and peddler stole the 30 kronor next morning","C":"Gave a horse","D":"Ignored him"}'::jsonb, 'B', 'MCQ', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 1, 'Peddler betrayed warm hospitality, getting trapped in gloomy woods soon after.', NULL, NULL, 'Peddler betrayed warm hospitality, getting trapped in gloomy woods soon after.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000011', 'Why did Edla Willmansson insist her ironmaster father let the stranger stay on Christmas Eve even after knowing he wasn''t Nils Olof?', '{"A":"She feared police","B":"Out of genuine compassion, wanting one day of peace for a poor hunted wretch chased away everywhere","C":"She needed help at forge","D":"She wanted gifts"}'::jsonb, 'B', 'MCQ', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 1, 'Unconditional human dignity awakened the peddler''s conscience.', NULL, NULL, 'Unconditional human dignity awakened the peddler''s conscience.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000012', 'What parting Christmas gift did the peddler leave inside Edla''s room?', '{"A":"A gold watch","B":"A small rattrap enclosing the stolen 30 kronor (to return to the crofter) and a letter signed \"Captain von Stahle\"","C":"A coat","D":"Nothing"}'::jsonb, 'B', 'MCQ', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 1, 'Edla treating him like a real Captain raised him to act like one.', NULL, NULL, 'Edla treating him like a real Captain raised him to act like one.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000013', 'How did Douglas''s swimming instructor turn him into a confident swimmer piece by piece?', NULL, NULL, 'VSA', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 2, 'Using belt-pulley rope safety for 3 months, teaching face-underwater exhalation/inhalation, leg-kicking at pool edge for weeks, and assembling strokes over 7 months before Lake Wentworth & Warm Lake solo swims cured residual terror.', 'Stepwise pulley/breath/stroke training + Lake swim test (2M)', NULL, 'Using belt-pulley rope safety for 3 months, teaching face-underwater exhalation/inhalation, leg-kicking at pool edge for weeks, and assembling strokes over 7 months before Lake Wentworth & Warm Lake solo swims cured residual terror.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000014', 'Explain Roosevelt''s famous quote cited by Douglas: "All we have to fear is fear itself."', NULL, NULL, 'VSA', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 2, 'Physical danger itself lasts briefly, whereas lingering psychological panic paralyses joy and willpower; confronting fear directly at Lake Wentworth stripped terror of power.', 'Fear vs real hazard explanation (2M)', NULL, 'Physical danger itself lasts briefly, whereas lingering psychological panic paralyses joy and willpower; confronting fear directly at Lake Wentworth stripped terror of power.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000015', 'Why did the peddler NOT correct the ironmaster when mistaken for old regimental comrade Captain Nils Olof at Ramsjö Ironworks?', NULL, NULL, 'VSA', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 2, 'He hoped the rich ironmaster might throw him a couple of kronor; when invited to the manor house, however, stealing 30 kronor made going there feel like "throwing himself into a lion''s den".', 'Kronor hope vs fear of manor trap (2M)', NULL, 'He hoped the rich ironmaster might throw him a couple of kronor; when invited to the manor house, however, stealing 30 kronor made going there feel like "throwing himself into a lion''s den".', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000016', '(i) What instantly changed the peddler''s heart during Christmas morning church service? (ii) Why did Edla feel dejected driving home from church? (iii) How had Edla raised the peddler to "Captain von Stahle"? (iv) Tone of Selam Lagerlof''s ending.', NULL, NULL, 'CASE', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 4, '(i) Hearing at church that the crofter''s guest was a rattrap thief awakened shame & gratitude toward Edla. (ii) Believing they sheltered a thief who likely stole their silver spoons. (iii) By trusting and honouring him like a real gentleman rather than judging his rags. (iv) Redemptive, heartwarming, uplifting.', '4 × 1M = 4M', 'Context: Walking out of Christmas church pale with shock after hearing a rattrap peddler had robbed an old crofter, Edla braced for an empty house—only to be greeted by an untouched silver closet and a tiny parcel.', '(i) Hearing at church that the crofter''s guest was a rattrap thief awakened shame & gratitude toward Edla. (ii) Believing they sheltered a thief who likely stole their silver spoons. (iii) By trusting and honouring him like a real gentleman rather than judging his rags. (iv) Redemptive, heartwarming, uplifting.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000017', 'Trace Douglas''s three exhausting failed attempts to surface in the 9-foot pool and how peaceful blackness eventually taught him to value life.', NULL, NULL, 'CASE', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 4, 'First jump came up slowly like paralysis; second jump brought zero air; third sucked water leaving limbs lifeless and curtain of life falling peacefully — motivating his lifelong grit to defeat residual phobia years later.', 'Panic & 3 attempts (2M) + Deeper appreciation of life (2M)', NULL, 'First jump came up slowly like paralysis; second jump brought zero air; third sucked water leaving limbs lifeless and curtain of life falling peacefully — motivating his lifelong grit to defeat residual phobia years later.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000018', '"Empathy and perseverance unlock hidden human potential." Discuss how systematic determination conquered phobic paralysis in "Deep Water" and how Edla''s compassionate respect redeemed the cynical peddler in "The Rattrap".', NULL, NULL, 'LA', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 5, 'Douglas refused to stay robbed of fishing, canoeing, and swimming; 7 months of disciplined pulley/breath drills plus swimming across Lake Wentworth & Warm Lake broke years of childhood trauma. Similarly, Selam Lagerlof proves punitive lectures never reform broken souls—Edla''s quiet kindness, fur coat, and trust gave the peddler moral elevation to return 30 kronor and sign himself Captain von Stahle.', 'Douglas grit (2.5M) + Edla redemption (2.5M)', NULL, 'Douglas refused to stay robbed of fishing, canoeing, and swimming; 7 months of disciplined pulley/breath drills plus swimming across Lake Wentworth & Warm Lake broke years of childhood trauma. Similarly, Selam Lagerlof proves punitive lectures never reform broken souls—Edla''s quiet kindness, fur coat, and trust gave the peddler moral elevation to return 30 kronor and sign himself Captain von Stahle.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000019', 'FLAMINGO PROSE EXTRACT (6 × 1M):
(i) Where did Douglas test whether any vestige of the old terror remained? (ii) What happened in the middle of the lake? (iii) How did Douglas address his returning fear ("Well, Mr Terror...")? (iv) Contrast "miniature" terror at Stamp Act Island vs old pool panic. (v) Literary device in addressing Terror. (vi) Central takeaway of Douglas''s victory.', NULL, NULL, 'CASE', 'English Core', 'Deep Water & The Rattrap (Flamingo)', 6, '(i) Swimming two miles across Lake Wentworth (New Hampshire) from Triggs Island to Stamp Act Island. (ii) Put his face under and saw nothing but bottomless dark water; the old sensation returned in miniature. (iii) Laughed defiantly: "Well, Mr Terror, what do you think you can do to me?" (iv) Fleeting tiny echo easily laughed off vs paralysing suffocation. (v) Personification / Apostrophe. (vi) Courage grows by confronting fear persistently until it dissolves.', '6 × 1M = 6M', 'Once confident in the pool, Douglas remained unsure whether old panic might return in open water, so he swam two miles straight across Lake Wentworth—putting his face under midway only to laugh off a miniature echo of Mr Terror before swimming on.', '(i) Swimming two miles across Lake Wentworth (New Hampshire) from Triggs Island to Stamp Act Island. (ii) Put his face under and saw nothing but bottomless dark water; the old sensation returned in miniature. (iii) Laughed defiantly: "Well, Mr Terror, what do you think you can do to me?" (iv) Fleeting tiny echo easily laughed off vs paralysing suffocation. (v) Personification / Apostrophe. (vi) Courage grows by confronting fear persistently until it dissolves.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000001a', 'Why did Rajkumar Shukla follow Mahatma Gandhi relentlessly from Lucknow to Cawnpore, Ahmedabad, and Calcutta?', '{"A":"For money","B":"To bring Gandhi to Champaran to fight the unjust 15% indigo sharecropping landlord system","C":"To join ashram","D":"For legal degree"}'::jsonb, 'B', 'MCQ', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 1, 'Resolute illiterate peasant persuaded Gandhi to visit Bihar.', NULL, NULL, 'Resolute illiterate peasant persuaded Gandhi to visit Bihar.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000001b', 'Why did Gandhi agree to 25% refund from British planters instead of holding out for 50%?', '{"A":"He lacked lawyers","B":"Amount mattered less than planters surrendering part of their money and, with it, their prestige/invincibility","C":"He was tired","D":"Court ordered it"}'::jsonb, 'B', 'MCQ', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 1, 'First civil disobedience triumph broke peasants'' fear.', NULL, NULL, 'First civil disobedience triumph broke peasants'' fear.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000001c', 'In "Poets and Pancakes", what was "Pancake" and why did Subbu stand No. 2 at Gemini Studios?', '{"A":"Breakfast dish","B":"Make-up brand trucked into Gemini; Kothamangalam Subbu was tailor-made for films with cheerful loyalty & versatile creativity","C":"Camera lens","D":"Stage curtain"}'::jsonb, 'B', 'MCQ', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 1, 'Asokamitran''s witty satire of 1940s Madras film studio hierarchy.', NULL, NULL, 'Asokamitran''s witty satire of 1940s Madras film studio hierarchy.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000001d', 'Who was the mysterious Englishman whose 1950 speech at Gemini Studios puzzled everyone until Stephen Spender''s book "The God That Failed" revealed him?', '{"A":"T.S. Eliot","B":"British poet Stephen Spender (editor of Encounter)","C":"George Orwell","D":"W.H. Auden"}'::jsonb, 'B', 'MCQ', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 1, 'Spender''s disillusionment with communism solved the years-old mystery.', NULL, NULL, 'Spender''s disillusionment with communism solved the years-old mystery.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000001e', 'In "The Interview", why did Umberto Eco call himself a university professor who writes novels on Sundays, explaining "interstices"?', '{"A":"He disliked novels","B":"Using tiny empty gaps of time (e.g., waiting for an elevator) let him write massive scholarly and bestselling work like The Name of the Rose","C":"He was idle","D":"Law forced it"}'::jsonb, 'B', 'MCQ', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 1, 'Working in spare "interstices" + storytelling academic style.', NULL, NULL, 'Working in spare "interstices" + storytelling academic style.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000001f', 'In "Going Places", what unrealistic hero-worship daydream did teenage Sophie cling to despite Jansie''s realism?', '{"A":"Becoming a doctor","B":"Claiming Irish football prodigy Danny Casey met her in the arcade and promised a date by the canal","C":"Moving to Paris","D":"Winning lottery"}'::jsonb, 'B', 'MCQ', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 1, 'Working-class escapist fantasy clashing with biscuit-factory reality.', NULL, NULL, 'Working-class escapist fantasy clashing with biscuit-factory reality.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000020', 'Why did Gandhiji scold Muzaffarpur lawyers before launching the Champaran inquiry?', NULL, NULL, 'VSA', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 2, 'He chided them for charging huge fees from crushed sharecroppers, urging instead that going to law courts was useless while peasants remained fear-stricken ("Freedom from fear is the real relief").', 'Fees critique + Freedom from fear (2M)', NULL, 'He chided them for charging huge fees from crushed sharecroppers, urging instead that going to law courts was useless while peasants remained fear-stricken ("Freedom from fear is the real relief").', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000021', 'Why do some writers like V.S. Naipaul and Rudyard Kipling dislike interviews while Umberto Eco embraces them?', NULL, NULL, 'VSA', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 2, 'Kipling called it an assault/crime; Naipaul felt people are wounded by losing parts of themselves. Eco finds interviews comfortable philosophical conversations clarifying his ideas.', 'Critics (1M) + Eco positive view (1M)', NULL, 'Kipling called it an assault/crime; Naipaul felt people are wounded by losing parts of themselves. Eco finds interviews comfortable philosophical conversations clarifying his ideas.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000022', 'Contrast practical Jansie with dreamy Sophie in "Going Places".', NULL, NULL, 'VSA', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 2, 'Jansie is grounded ("both earmarked for the biscuit factory") warning Sophie against wild boutique/actress fantasies; Sophie lives in glamorous escapist daydreams around Danny Casey.', '1M each', NULL, 'Jansie is grounded ("both earmarked for the biscuit factory") warning Sophie against wild boutique/actress fantasies; Sophie lives in glamorous escapist daydreams around Danny Casey.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000023', '(i) How did synthetic indigo developed in Germany trigger Champaran''s crisis? (ii) What social/medical improvements did Gandhi bring to Champaran villages beyond politics? (iii) How did Gandhi teach Indian followers "self-reliance" when rejecting C.F. Andrews'' help? (iv) Contrast Gandhi''s court confession at Motihari.', NULL, NULL, 'CASE', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 4, '(i) Landlords didn''t need natural indigo anymore, yet demanded compensation cash to release peasants from 15% contracts. (ii) Opened 6 village primary schools, Kasturba taught sanitation, doctors volunteered castor oil/quinine/sulphur ointment. (iii) Refused relying on an Englishman as a crutch ("our cause is just; rely upon yourselves"). (iv) Conflict of duties: obeyed higher law of conscience over British magistrate order.', '4 × 1M = 4M', 'Context: Refusing to remain merely a political agitation, Gandhi mobilised volunteer teachers, doctors, and Kasturbai to uplift hygiene and literacy across six Champaran villages.', '(i) Landlords didn''t need natural indigo anymore, yet demanded compensation cash to release peasants from 15% contracts. (ii) Opened 6 village primary schools, Kasturba taught sanitation, doctors volunteered castor oil/quinine/sulphur ointment. (iii) Refused relying on an Englishman as a crutch ("our cause is just; rely upon yourselves"). (iv) Conflict of duties: obeyed higher law of conscience over British magistrate order.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000024', 'Show how Umberto Eco explains the surprising massive success of his serious medieval detective novel "The Name of the Rose".', NULL, NULL, 'CASE', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 4, 'Journalists expected puzzles/theology to bore readers, yet ~10–15 million copies sold — proving readers do NOT only like "trash" and often enjoy difficult historical-philosophical narratives if timed rightly.', 'Novel nature (2M) + Audience insight (2M)', NULL, 'Journalists expected puzzles/theology to bore readers, yet ~10–15 million copies sold — proving readers do NOT only like "trash" and often enjoy difficult historical-philosophical narratives if timed rightly.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000025', 'Compare Realist Social Action in "Indigo" (Gandhi solving systemic peasant exploitation) with Adolescent Fantasy vs Working-Class Reality in "Going Places" (Sophie).', NULL, NULL, 'LA', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 5, 'Gandhi anchors transformative change in rigorous fact-finding (10,000 peasant depositions), polite unyielding moral courage at Motihari court, and grassroots sanitation/schooling. Conversely, A.R. Barton''s Sophie escapes damp cramped tenement reality and biscuit-factory fate by inventing meetings with star footballer Danny Casey — ending lonely by the canal unable to stop wishing.', 'Indigo pragmatism (2.5M) + Sophie escapism (2.5M)', NULL, 'Gandhi anchors transformative change in rigorous fact-finding (10,000 peasant depositions), polite unyielding moral courage at Motihari court, and grassroots sanitation/schooling. Conversely, A.R. Barton''s Sophie escapes damp cramped tenement reality and biscuit-factory fate by inventing meetings with star footballer Danny Casey — ending lonely by the canal unable to stop wishing.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000026', 'FLAMINGO PROSE EXTRACT (6 × 1M):
(i) Why did the office boy in Make-up Department feel bitter toward Subbu? (ii) What age was the "office boy" actually? (iii) What had he originally hoped to become upon joining Gemini Studios? (iv) What gentle irony is conveyed by "crowd-shooting days"? (v) Who wrote "Poets and Pancakes"? (vi) Meaning of "ignominy" / "bafflement".', NULL, NULL, 'CASE', 'English Core', 'Indigo, Poets & Pancakes, Interview & Going Places', 6, '(i) Blamed Subbu for his own thwarted literary/acting career despite having zero proof. (ii) In his early forties! (iii) A star actor, top screenwriter, director, or lyrics writer. (iv) He only got to paint bucket-loads of pancake onto extras during crowd scenes. (v) Asokamitran. (vi) Public shame / complete confusion.', '6 × 1M = 6M', 'In Gemini Studios'' upstairs make-up room, an "office boy" in his early forties still mixed pancake paste in huge vessels on crowd-shooting days, convinced that his poetic talent was crushed simply because Subbu enjoyed the Boss''s ear.', '(i) Blamed Subbu for his own thwarted literary/acting career despite having zero proof. (ii) In his early forties! (iii) A star actor, top screenwriter, director, or lyrics writer. (iv) He only got to paint bucket-loads of pancake onto extras during crowd scenes. (v) Asokamitran. (vi) Public shame / complete confusion.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000027', 'In Kamala Das''s "My Mother at Sixty-Six", what do "Young Trees sprinting" and "merry children spilling out" symbolise?', '{"A":"Speed of train","B":"Vibrant energetic youth contrasting starkly with the aging mother''s pale \"late winter''s moon\" stillness","C":"Picnic spot","D":"Summer heat"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 1, 'Sharp visual contrast intensifies daughter''s separation fear.', NULL, NULL, 'Sharp visual contrast intensifies daughter''s separation fear.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000028', 'Why did Kamala Das repeat "smile and smile and smile..." while bidding goodbye at Cochin airport?', '{"A":"She was thrilled to fly","B":"Concealing aching childhood fear of losing her frail mother under a reassuring brave farewell smile","C":"Photographer asked her","D":"Friends waited"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 1, 'Repetition underlines forced courage hiding helplessness.', NULL, NULL, 'Repetition underlines forced courage hiding helplessness.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000029', 'In Pablo Neruda''s "Keeping Quiet", why does he clarify "I want no truck with death" right after urging 12 seconds of stillness?', '{"A":"He dislikes trucks","B":"Stillness means mindful introspection and peaceful suspension of harm — NOT total inactivity or death","C":"War was over","D":"Counting game"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 1, 'Introspection revives life like Earth under winter dormancy.', NULL, NULL, 'Introspection revives life like Earth under winter dormancy.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000002a', 'What "green wars" does Neruda condemn in "Keeping Quiet"?', '{"A":"Gardening","B":"Wars against environment/forests, gas warfare, and destructive fire leaving \"victory with no survivors\"","C":"Sports matches","D":"Farming"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 1, 'Ecological violence & lethal weapons destroy humanity itself.', NULL, NULL, 'Ecological violence & lethal weapons destroy humanity itself.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000002b', 'According to John Keats in "A Thing of Beauty", beauty never passes into nothingness because:', '{"A":"Paintings stay costly","B":"A thing of beauty is a \"joy forever\", growing in loveliness and providing a quiet shady bower of sweet dreams and health","C":"Flowers never wilt","D":"Gold lasts"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 1, 'Opening couplet of Endymion celebrates eternal aesthetic solace.', NULL, NULL, 'Opening couplet of Endymion celebrates eternal aesthetic solace.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000002c', 'What "endless fountain of immortal drink" pours unto us from the heaven''s brink in Keats''s poem?', '{"A":"Rainwater","B":"Nature''s boundless inspiring beauty alongside noble \"grandeur of the dooms\" and tales of heroic ancestors","C":"Nectar jars","D":"Mountain springs"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 1, 'Links nature''s beauty with inspiring human heritage.', NULL, NULL, 'Links nature''s beauty with inspiring human heritage.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000002d', 'Explain the two similes used by Kamala Das to describe her dozing 66-year-old mother.', NULL, NULL, 'VSA', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 2, '"Ashen like that of a corpse" conveys lifeless pallor; "pale as a late winter''s moon" conveys dim fading warmth veiled by wintry mist.', '1M each', NULL, '"Ashen like that of a corpse" conveys lifeless pallor; "pale as a late winter''s moon" conveys dim fading warmth veiled by wintry mist.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000002e', 'Explain Pablo Neruda''s "Earth can teach us" lesson at the end of "Keeping Quiet".', NULL, NULL, 'VSA', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 2, 'When everything seems frozen and dead during harsh winter, Earth quietly nurtures seeds beneath the surface and proves alive again in spring — teaching calm quietness fosters renewal.', 'Winter dormancy -> Spring renewal (2M)', NULL, 'When everything seems frozen and dead during harsh winter, Earth quietly nurtures seeds beneath the surface and proves alive again in spring — teaching calm quietness fosters renewal.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000002f', '(i) List two causes of human gloom ("despondence") mentioned by John Keats. (ii) How does a "flowery band" act in our lives? (iii) Name four specific natural objects of beauty Keats lists. (iv) Explain "cooling covert" and "mighty dead".', NULL, NULL, 'CASE', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 4, '(i) Inhuman dearth of noble natures, gloomy days, and unhealthy/darkened ways. (ii) Binds us spiritually to the Earth each morning despite sorrow. (iii) Sun, moon, old & young trees, sheep, daffodils, clear rills, musk-rose blooms. (iv) Shady thicket shielding sheep/travellers from summer heat; noble brave ancestors remembered in inspiring tales.', '4 × 1M = 4M', 'Context: "Therefore, on every morrow, are we wreathing / A flowery band to bind us to the earth, / Spite of despondence, of the inhuman dearth / Of noble natures..."', '(i) Inhuman dearth of noble natures, gloomy days, and unhealthy/darkened ways. (ii) Binds us spiritually to the Earth each morning despite sorrow. (iii) Sun, moon, old & young trees, sheep, daffodils, clear rills, musk-rose blooms. (iv) Shady thicket shielding sheep/travellers from summer heat; noble brave ancestors remembered in inspiring tales.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000030', 'How will 12 seconds of counting and pausing unite fishermen, salt-gatherers, and warmongers in "Keeping Quiet"?', NULL, NULL, 'CASE', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 4, 'Fishermen stop harming whales; salt-gatherers pause to look at their hurt hands; warmongers put on clean clothes and walk peacefully as brothers under shade — turning destructive rush into compassionate reflection.', 'All 3 groups cleanly covered (4M)', NULL, 'Fishermen stop harming whales; salt-gatherers pause to look at their hurt hands; warmongers put on clean clothes and walk peacefully as brothers under shade — turning destructive rush into compassionate reflection.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000031', 'Compare how Nature serves as a mirror of inner fear in "My Mother at Sixty-Six" vs an eternal balm for human despair in "A Thing of Beauty" and teacher of renewal in "Keeping Quiet".', NULL, NULL, 'LA', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 5, 'Kamala Das contrasts outside racing trees and joyful children against her mother''s fragile mortality, sharpening bittersweet separation. Keats elevates nature (daffodils, clear rills, musk-roses) and heroic lore into an immortal soothing sanctuary lifting dark pall from human spirits. Neruda invites humanity to mimic Earth''s quiet winter pause to heal ecological and military violence.', 'Kamala Das (1.5M) + Keats (2M) + Neruda (1.5M)', NULL, 'Kamala Das contrasts outside racing trees and joyful children against her mother''s fragile mortality, sharpening bittersweet separation. Keats elevates nature (daffodils, clear rills, musk-roses) and heroic lore into an immortal soothing sanctuary lifting dark pall from human spirits. Neruda invites humanity to mimic Earth''s quiet winter pause to heal ecological and military violence.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000032', 'FLAMINGO POETRY EXTRACT (6 × 1M):
(i) Where was the poet driving from, and when? (ii) What visual detail alerted her to her mother''s frailty? (iii) Explain "familiar ache". (iv) Why does she look outside at sprinting trees? (v) Poetic device in "Young Trees sprinting". (vi) Tone of the final farewell line.', NULL, NULL, 'CASE', 'English Core', 'Flamingo Poetry (My Mother at Sixty-Six, Quiet, Thing of Beauty)', 6, '(i) From her parents'' home to Cochin airport on a Friday morning. (ii) Mother dozing beside her with mouth open, face pale as a corpse. (iii) Old childhood dread of separation and mother''s eventual death. (iv) To distract/put away that painful thought with lively movement outside. (v) Personification. (vi) Poignant, brave, reassuring despite suppressed tears.', '6 × 1M = 6M', 'Driving from my parent''s home to Cochin last Friday morning, I saw my mother beside me, doze, open mouthed, her face ashen like that of a corpse, and realised with pain that she was as old as she looked—quickly turning away to watch Young Trees sprinting.', '(i) From her parents'' home to Cochin airport on a Friday morning. (ii) Mother dozing beside her with mouth open, face pale as a corpse. (iii) Old childhood dread of separation and mother''s eventual death. (iv) To distract/put away that painful thought with lively movement outside. (v) Personification. (vi) Poignant, brave, reassuring despite suppressed tears.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000033', 'In Robert Frost''s "A Roadside Stand", what did the poor rural shed owners desperately hope for from passing city traffic?', '{"A":"Free food","B":"Some \"city money\" earned honestly from selling wild berries and squash to brighten their cramped lives","C":"Political speeches","D":"Newspaper"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 1, 'Not charity dole, just cash circulation promised by movies/politicians.', NULL, NULL, 'Not charity dole, just cash circulation promised by movies/politicians.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000034', 'Who are the "greedy good-doers, beneficent beasts of prey" in Frost''s poem?', '{"A":"Wild animals","B":"Selfish city developers & politicians pretending to help villagers by relocating them near theatres/stores while destroying self-reliance and sleep","C":"Tourists","D":"Shopkeepers"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 1, 'Biting oxymoron exposing exploitative fake philanthropy.', NULL, NULL, 'Biting oxymoron exposing exploitative fake philanthropy.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000035', 'What "massive weight of Uncle''s wedding band" sits heavily upon Aunt Jennifer''s fluttering hand?', '{"A":"Heavy gold price","B":"Oppressive patriarchal burden, domestic anxiety, and marital subjugation throughout her life","C":"Arthritis","D":"Embroidery frame"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 1, 'Wedding ring symbolises lifelong entrapment.', NULL, NULL, 'Wedding ring symbolises lifelong entrapment.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000036', 'How do Aunt Jennifer''s embroidered bright topaz tigers contrast with Aunt Jennifer herself?', '{"A":"Tigers are weak","B":"Tigers prance fearless, chivalric, and proud forever on the tapestry even after her terrified ringed hands lie dead","C":"They sleep calmly","D":"They look dull"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 1, 'Art achieves immortal freedom denied to the artist in life.', NULL, NULL, 'Art achieves immortal freedom denied to the artist in life.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000037', 'Why did polished city cars stop briefly at the Roadside Stand only to annoy the farmer?', '{"A":"To buy apples","B":"To reverse on the grass ruining turf, ask directions, ask for gas (petrol), or complain that crooked N/S signs spoiled mountain view","C":"To donate","D":"To rest"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 1, 'Indifferent urban arrogance deepens rural isolation.', NULL, NULL, 'Indifferent urban arrogance deepens rural isolation.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000038', 'Explain the poetic phrase "trusting sorrow" in "A Roadside Stand":', '{"A":"Happy smile","B":"Quiet heartbreak of poor villagers who trusted false promises of prosperity only to be ignored day after day","C":"Bank loan","D":"Angry mob"}'::jsonb, 'B', 'MCQ', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 1, 'Unsaid hurt of broken civic promises.', NULL, NULL, 'Unsaid hurt of broken civic promises.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000039', 'Why did Robert Frost briefly confess a "childish longing" to end villagers'' pain at one stroke, before regretting it next morning?', NULL, NULL, 'VSA', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 2, 'Watching hopeless "open prayer" at the shed window broke his heart into wanting merciful release, yet sane reflection reminded him how unbearable such intrusion would feel if done to him.', 'Emotional empathy (1M) + Sane reversal (1M)', NULL, 'Watching hopeless "open prayer" at the shed window broke his heart into wanting merciful release, yet sane reflection reminded him how unbearable such intrusion would feel if done to him.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000003a', 'Explain why Aunt Jennifer''s fingers "fluttering through her wool" find even the light ivory needle hard to pull.', NULL, NULL, 'VSA', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 2, 'Psychological trauma and fear built over decades of patriarchal domination make her trembling nervous fingers physically weak.', 'Trauma & oppression anxiety (2M)', NULL, 'Psychological trauma and fear built over decades of patriarchal domination make her trembling nervous fingers physically weak.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000003b', '(i) Describe the visual imagery of Aunt Jennifer''s tigers ("bright topaz denizens"). (ii) Why do the tigers "not fear the men beneath the tree"? (iii) What happens to Aunt Jennifer''s "ordeals" even in death ("When Aunt is dead")? (iv) Contrast permanence of art vs fragility of human life.', NULL, NULL, 'CASE', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 4, '(i) Bright golden-yellow topaz creatures glowing against lush green forest tapestry. (ii) They embody fearless confidence and unrestrained power unlike Aunt Jennifer who feared her husband. (iii) Even her corpse remains ringed/mastered by lifelong oppressive marriage. (iv) Oppressed mortal life ends, yet artistic creation endures proudly forever.', '4 × 1M = 4M', 'Context: "When Aunt is dead, her terrified hands will lie / Still ringed with ordeals she was mastered by. / The tigers in the panel that she made / Will go on prancing, proud and unafraid."', '(i) Bright golden-yellow topaz creatures glowing against lush green forest tapestry. (ii) They embody fearless confidence and unrestrained power unlike Aunt Jennifer who feared her husband. (iii) Even her corpse remains ringed/mastered by lifelong oppressive marriage. (iv) Oppressed mortal life ends, yet artistic creation endures proudly forever.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000003c', 'Show how Robert Frost uses Oxymoron and Personification in "A Roadside Stand" to indict urban apathy.', NULL, NULL, 'CASE', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 4, 'Oxymorons "greedy good-doers" & "beneficent beasts of prey" unmask exploitative welfare schemes ("enforcing benefits... soothing them out of their wits"); "The sadness that lurks near the open window" personifies hopeless daily waiting.', 'Oxymorons (2M) + Personification (2M)', NULL, 'Oxymorons "greedy good-doers" & "beneficent beasts of prey" unmask exploitative welfare schemes ("enforcing benefits... soothing them out of their wits"); "The sadness that lurks near the open window" personifies hopeless daily waiting.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000003d', 'Compare Social & Gender Oppression in Robert Frost''s "A Roadside Stand" (urban-rural economic divide) and Adrienne Rich''s "Aunt Jennifer''s Tigers" (domestic patriarchy).', NULL, NULL, 'LA', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 5, 'Frost amplifies the silent "childish longing" of marginalised countryside farmers ignored by speeding polished traffic and manipulated by calculating developers promising false welfare. Rich turns inward to domestic confinement, where a timid woman channels suppressed courage into prancing emerald-forest tigers that outlive the heavy wedding band mastering her fingers.', 'Frost rural neglect (2.5M) + Rich patriarchy & art (2.5M)', NULL, 'Frost amplifies the silent "childish longing" of marginalised countryside farmers ignored by speeding polished traffic and manipulated by calculating developers promising false welfare. Rich turns inward to domestic confinement, where a timid woman channels suppressed courage into prancing emerald-forest tigers that outlive the heavy wedding band mastering her fingers.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000003e', 'FLAMINGO POETRY EXTRACT (6 × 1M):
(i) What "little new shed" was erected beside the sped-up highway? (ii) Did the rural owners beg for "dole of bread"? (iii) Explain "whose flow supports the flower of cities from sinking". (iv) Why did passing city folk complain at the scenic mountain view? (v) Rhyme/poetic effect of "pathetic plea". (vi) Author of "A Roadside Stand".', NULL, NULL, 'CASE', 'English Core', 'Flamingo Poetry (Roadside Stand & Aunt Jennifer''s Tigers)', 6, '(i) A modest roadside stand extending an old peasant house to sell farm berries and squash. (ii) No — they sought fair economic trade ("some of the money, the cash") rather than demeaning alms. (iii) Cash circulation sustains affluent city luxuries just as farmers seek a tiny share. (iv) Claimed clumsy painted N/S signs marred artless landscape beauty. (v) Alliteration underscoring quiet desperation. (vi) Robert Frost.', '6 × 1M = 6M', 'The little old house was out with a little new shed in front at the edge of the road where the traffic sped, a roadside stand that too pathetically pled — not for a dole of bread, but for some of the cash whose flow supports the flower of cities from sinking.', '(i) A modest roadside stand extending an old peasant house to sell farm berries and squash. (ii) No — they sought fair economic trade ("some of the money, the cash") rather than demeaning alms. (iii) Cash circulation sustains affluent city luxuries just as farmers seek a tiny share. (iv) Claimed clumsy painted N/S signs marred artless landscape beauty. (v) Alliteration underscoring quiet desperation. (vi) Robert Frost.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000003f', 'What did Charley claim to have stumbled upon at Grand Central Station in Jack Finney''s "The Third Level"?', '{"A":"A hidden treasure vault","B":"A portal to the year 1894 (two-tier station having an 1894 third level with brass spittoons, locomotives, and The World newspaper dated June 11, 1894)","C":"A secret metro","D":"An airport"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: The Third Level & The Tiger King', 1, 'Confirmed by Sam''s first-day cover letter dated July 18, 1894 in Galesburg.', NULL, NULL, 'Confirmed by Sam''s first-day cover letter dated July 18, 1894 in Galesburg.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000040', 'How did psychiatrist Sam Weiner initially diagnose Charley''s Third Level experience — until Sam himself vanished there?', '{"A":"Brain fever","B":"\"A waking-dream wish fulfilment\" — escaping modern insecurity, fear, war, and worry","C":"Sleepwalking","D":"Colour blindness"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: The Third Level & The Tiger King', 1, 'Sam later bought $800 of old currency to start hay/feed business in 1894 Galesburg!', NULL, NULL, 'Sam later bought $800 of old currency to start hay/feed business in 1894 Galesburg!', 'EASY', true),
        ('12051111-0000-4000-8000-000000000041', 'In Kalki''s "The Tiger King", what miraculous prophecy did the royal astrologer utter when Prince Jung Jung Bahadur was just 10 days old?', '{"A":"He would become rich","B":"Since born in the hour of the Bull (enemy of Tiger), his death would come from a Tiger — prompting the infant to speak \"Let tigers beware!\"","C":"He would rule Europe","D":"He would fail"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: The Third Level & The Tiger King', 1, 'Specifically warned: "Beware of the hundredth tiger!"', NULL, NULL, 'Specifically warned: "Beware of the hundredth tiger!"', 'EASY', true),
        ('12051111-0000-4000-8000-000000000042', 'What ironic twist actually killed the Maharaja of Pratibandapuram after he thought he shot 100 tigers?', '{"A":"Another wild tiger","B":"A tiny wooden sliver from a cheap crooked toy tiger bought for his son''s 3rd birthday infected his right hand, causing fatal suppuration","C":"A snake bite","D":"Old age"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: The Third Level & The Tiger King', 1, 'Three famous Madras surgeons declared "The operation was successful. The Maharaja is dead."', NULL, NULL, 'Three famous Madras surgeons declared "The operation was successful. The Maharaja is dead."', 'EASY', true),
        ('12051111-0000-4000-8000-000000000043', 'How many rings did the Tiger King gift the high-ranking British officer''s wife to save his throne after refusing a tiger hunt photo?', '{"A":"Five rings","B":"Fifty diamond rings worth ₹3 lakh (thinking she''d pick 1 or 2, she kept ALL 50!)","C":"Ten gold coins","D":"One silver tray"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: The Third Level & The Tiger King', 1, 'Satire on colonial bribery and royal vanity.', NULL, NULL, 'Satire on colonial bribery and royal vanity.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000044', 'Where did old Dewan secretly obtain the weak elderly 100th tiger from to save his own job?', '{"A":"Sundarbans","B":"People''s Park in Madras (kept hidden in his house until driven to the forest)","C":"Africa","D":"Nepal"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: The Third Level & The Tiger King', 1, 'Hunters killed the fainted tiger quietly because Maharaja''s shot missed.', NULL, NULL, 'Hunters killed the fainted tiger quietly because Maharaja''s shot missed.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000045', 'What is a "First-Day Cover" in stamp collecting, and how did Sam''s letter inside Grandpa''s collection prove 1894 real to Charley?', NULL, NULL, 'VSA', 'English Core', 'Vistas: The Third Level & The Tiger King', 2, 'When a new stamp issues, collectors mail blank paper inside self-addressed envelopes on Day 1 for the postmark date. Charley found an 1894 Galesburg cover containing a real note from Sam urging him to keep looking for the Third Level.', 'First-day cover (1M) + Sam letter proof (1M)', NULL, 'When a new stamp issues, collectors mail blank paper inside self-addressed envelopes on Day 1 for the postmark date. Charley found an 1894 Galesburg cover containing a real note from Sam urging him to keep looking for the Third Level.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000046', 'Why did the Maharaja double land tax on villagers when the 100th tiger couldn''t be found, and how did his Dewan rescue the kingdom?', NULL, NULL, 'VSA', 'English Core', 'Vistas: The Third Level & The Tiger King', 2, 'Furious at stopping at 99 tigers, he threatened Dewan with dismissal and doubled villagers'' tax. Panicked Dewan fetched an aged zoo tiger from Madras and pushed it onto the Maharaja''s hunting ground.', 'Tax rage (1M) + Zoo tiger trick (1M)', NULL, 'Furious at stopping at 99 tigers, he threatened Dewan with dismissal and doubled villagers'' tax. Panicked Dewan fetched an aged zoo tiger from Madras and pushed it onto the Maharaja''s hunting ground.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000047', 'VISTAS EXTRACT (4 × 1M):
(i) Contrast Charley''s modern New York stress vs Galesburg, Illinois in 1894. (ii) Why couldn''t Charley buy two tickets to Galesburg at the Third Level counter? (iii) How much did Charley lose converting $300 into old-style 1894 bills? (iv) Significance of Grand Central growing like a tree.', NULL, NULL, 'CASE', 'English Core', 'Vistas: The Third Level & The Tiger King', 4, '(i) Modern post-WWII insecurity, rush, and anxiety vs peaceful 1894 summer evenings with fireflies, wide lawns, and zero world wars. (ii) Clerk noticed modern currency looked like fake "skin" and threatened jail. (iii) Got under $200 in old bills, yet didn''t mind because eggs cost 13 cents a dozen in 1894! (iv) Endless corridors symbolise subconscious escape tunnels from stressful modernity.', '4 × 1M = 4M', 'Context: Pulling back from the 1894 ticket clerk staring suspiciously at modern bank notes, Charley rushed back out of Grand Central determined to trade his entire savings for old-style currency before returning to peace-filled Galesburg.', '(i) Modern post-WWII insecurity, rush, and anxiety vs peaceful 1894 summer evenings with fireflies, wide lawns, and zero world wars. (ii) Clerk noticed modern currency looked like fake "skin" and threatened jail. (iii) Got under $200 in old bills, yet didn''t mind because eggs cost 13 cents a dozen in 1894! (iv) Endless corridors symbolise subconscious escape tunnels from stressful modernity.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000048', 'Comment on Kalki''s satirical tone in "The Tiger King" targeting royal arrogance, sycophancy, and ecological cruelty.', NULL, NULL, 'CASE', 'English Core', 'Vistas: The Third Level & The Tiger King', 4, 'Kalki mocks sycophantic courtiers, absurd 10-year marriage selection purely for tiger population in in-laws'' state, ₹3 lakh diamond bribe, and fatal irony where an unassuming toy sliver avenges 99 slaughtered real tigers.', 'Arrogance & sycophancy (2M) + Ecological irony (2M)', NULL, 'Kalki mocks sycophantic courtiers, absurd 10-year marriage selection purely for tiger population in in-laws'' state, ₹3 lakh diamond bribe, and fatal irony where an unassuming toy sliver avenges 99 slaughtered real tigers.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000049', 'Contrast psychological escapism into peaceful nostalgia ("The Third Level") with reckless delusion of conquering fate and nature ("The Tiger King").', NULL, NULL, 'LA', 'English Core', 'Vistas: The Third Level & The Tiger King', 5, 'Charley yearns harmlessly for 1894 simplicity and gentle fellowship amid modern anxiety, blurring boundary between dream and reality cleanly via Sam''s letter. Conversely, the Tiger King wages a decades-long war against fate and wildlife, neglecting administration and destroying Pratibandapuram''s tiger population only to succumb comically to a wooden toy splinter.', 'Charley nostalgia (2.5M) + Tiger King hubris (2.5M)', NULL, 'Charley yearns harmlessly for 1894 simplicity and gentle fellowship amid modern anxiety, blurring boundary between dream and reality cleanly via Sam''s letter. Conversely, the Tiger King wages a decades-long war against fate and wildlife, neglecting administration and destroying Pratibandapuram''s tiger population only to succumb comically to a wooden toy splinter.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000004a', 'VISTAS EXTRACT (4 × 1M):
(i) Why did the Maharaja fire hunters or lower/raise rewards frantically? (ii) What happened when the Maharaja fired at the 100th weak tiger? (iii) Why didn''t the hunters tell the Maharaja he had missed? (iv) Irony of the surgeons'' verdict "Operation was successful".', NULL, NULL, 'CASE', 'English Core', 'Vistas: The Third Level & The Tiger King', 4, '(i) Desperate obsession to reach 100th kill so astrologer''s warning wouldn''t hang over him. (ii) Bullet missed; the frail beast merely fainted from the loud bang. (iii) Feared losing their jobs if Maharaja found the 100th tiger survived. (iv) Surgical triumph meant nothing since the patient (Maharaja) died — completing the astrologer''s prophecy via the 100th (wooden) tiger.', '4 × 1M = 4M', '"The Maharaja has killed the hundredth tiger!" — jubilant yet terrified to see the old beast slowly blinking from its swoon after the king''s jeep sped away, the hunters quietly took aim themselves from one foot away.', '(i) Desperate obsession to reach 100th kill so astrologer''s warning wouldn''t hang over him. (ii) Bullet missed; the frail beast merely fainted from the loud bang. (iii) Feared losing their jobs if Maharaja found the 100th tiger survived. (iv) Surgical triumph meant nothing since the patient (Maharaja) died — completing the astrologer''s prophecy via the 100th (wooden) tiger.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000004b', 'How many years ago did the giant southern supercontinent Gondwana thrive centred around present-day Antarctica?', '{"A":"1 million years","B":"650 million years ago (before breaking up ~150 million yrs ago when dinosaurs wiped out and India pushed north)","C":"5,000 years","D":"50 million years"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 1, '650 million years ago Gondwana enjoyed warm climate and rich flora/fauna.', NULL, NULL, '650 million years ago Gondwana enjoyed warm climate and rich flora/fauna.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000004c', 'What vital educational purpose does Geoff Green''s "Students on Ice" programme serve?', '{"A":"Touring ski resorts","B":"Taking high-school students (future policymakers) to Antarctica to witness collapsing ice shelves and climate change firsthand","C":"Mining minerals","D":"Hunting seals"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 1, 'Youth still absorb urgency and can act decisively.', NULL, NULL, 'Youth still absorb urgency and can act decisively.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000004d', 'What metaphor of Phytoplankton teaches Tishani Doshi a huge ecological lesson in Antarctica?', '{"A":"Deep roots","B":"\"Take care of small things and the big things will fall into place\" — tiny single-celled phytoplankton sustain the entire Southern Ocean food chain and global carbon cycle","C":"Icebergs melt slow","D":"Penguins swim fast"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 1, 'Ozone depletion harming microscopic phytoplankton collapses whales, birds, and carbon sinks.', NULL, NULL, 'Ozone depletion harming microscopic phytoplankton collapses whales, birds, and carbon sinks.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000004e', 'In Pearl S. Buck''s "The Enemy", why was Dr. Sadao Hoki NOT sent overseas with Japanese troops during WWII?', '{"A":"He refused","B":"He was perfecting a revolutionary medical discovery for cleaning wounds, AND the ailing old General might suddenly need Sadao''s surgery","C":"He was too old","D":"Poor eyesight"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 1, 'Both medical research and the General''s selfish dependence kept Sadao at home.', NULL, NULL, 'Both medical research and the General''s selfish dependence kept Sadao at home.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000004f', 'Why did Dr. Sadao and Hana save the washed-up American POW Tom despite risking arrest as traitors?', '{"A":"He offered money","B":"Sadao''s overriding Hippocratic medical oath (\"I have been trained not to let a man die if I can help it\") defeated wartime nationalism","C":"General ordered it","D":"Servants insisted"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 1, 'Humanity and professional medical ethics transcended enemy lines.', NULL, NULL, 'Humanity and professional medical ethics transcended enemy lines.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000050', 'Why did the Japanese General forget his promise to send private assassins to kill Tom cleanly?', '{"A":"Assassins escaped","B":"Self-absorbed by his own severe gallbladder pain/recovery, the General confessed it was purely careless forgetfulness — NOT lack of patriotism","C":"Police arrested them","D":"He pitied Tom"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 1, 'Prompted Sadao to give Tom his boat, flashlight, and Korean-boat escape plan.', NULL, NULL, 'Prompted Sadao to give Tom his boat, flashlight, and Korean-boat escape plan.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000051', 'Why is Antarctica called the ideal lab to study Earth''s Past, Present, and Future?', NULL, NULL, 'VSA', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 2, 'Never sustained permanent human population so its 90% ice-cap traps half-million-year-old carbon/climate records in ice cores while visibly showing modern glacial retreat.', 'Pristine past carbon records + Modern warming alerts (2M)', NULL, 'Never sustained permanent human population so its 90% ice-cap traps half-million-year-old carbon/climate records in ice cores while visibly showing modern glacial retreat.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000052', 'How did Sadao''s servants (Yumi, gardener, cook) react to sheltering the white American POW vs Hana and Sadao?', NULL, NULL, 'VSA', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 2, 'Superstitious servants felt horrified ("white man ought to die, first shot then sea") and quit service silently, whereas educated Hana/Sadao overcame repulsion to nurse and help him escape.', 'Servants rejection (1M) + Sadao/Hana humanity (1M)', NULL, 'Superstitious servants felt horrified ("white man ought to die, first shot then sea") and quit service silently, whereas educated Hana/Sadao overcame repulsion to nurse and help him escape.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000053', 'VISTAS EXTRACT (4 × 1M):
(i) How did Sadao instruct Tom to signal with the flashlight? (ii) What clothing/provisions did Sadao pack onto the boat? (iii) Why did Sadao still ponder "Why could I not kill him?" at the story''s end? (iv) Contrast Sadao''s father''s Japanese pride with Sadao''s universal humanity.', NULL, NULL, 'CASE', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 4, '(i) Two short flashes at dusk only if food ran low before catching a Korean fishing boat; never flash in open darkness. (ii) Quilts, Japanese clothes wrapped round blond head, bottled water, two blankets, raw fish guidance. (iii) Remembering prejudiced Americans (prof''s dirty room, insensitive landlady) made saving Tom seem an unexplainable triumph of pure medical conscience. (iv) Father insisted on pure Japanese traditions (waiting for verified pure Japanese wife Hana), yet Sadao proved moral duty spans all races.', '4 × 1M = 4M', 'Context: Waiting silently for three nights without seeing assassins arrive, Dr. Sadao quietly dragged out his sturdy boat, stocked it with extra quilts, water, and a flashlight, and pointed the recovered American prisoner toward the unguarded nearby island.', '(i) Two short flashes at dusk only if food ran low before catching a Korean fishing boat; never flash in open darkness. (ii) Quilts, Japanese clothes wrapped round blond head, bottled water, two blankets, raw fish guidance. (iii) Remembering prejudiced Americans (prof''s dirty room, insensitive landlady) made saving Tom seem an unexplainable triumph of pure medical conscience. (iv) Father insisted on pure Japanese traditions (waiting for verified pure Japanese wife Hana), yet Sadao proved moral duty spans all races.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000054', 'Explain how walking on 1-metre-thick frozen ocean ice at 65.55° South gave Tishani Doshi an epiphany about global interconnectedness.', NULL, NULL, 'CASE', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 4, 'Above 1 m ice and 180 m living ocean water, witnessing crabeater seals lounging just like stray dogs under Indian banyan trees made her marvel how everything in Earth''s biosphere connects — warning against unchecked fossil burning over mere 12,000 years of human presence.', 'Ocean walk experience (2M) + Interconnected climate message (2M)', NULL, 'Above 1 m ice and 180 m living ocean water, witnessing crabeater seals lounging just like stray dogs under Indian banyan trees made her marvel how everything in Earth''s biosphere connects — warning against unchecked fossil burning over mere 12,000 years of human presence.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000055', 'Explore how both "Journey to the End of the Earth" and "The Enemy" urge human beings to rise above narrow boundaries — ecological short-sightedness in the first, and wartime racial hatred in the second.', NULL, NULL, 'LA', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 5, 'Tishani Doshi zooms out to 650-million-year geological history, proving human civilisation occupies barely 12 seconds on a planetary clock yet threatens whole food webs via global warming unless youth protect small things like phytoplankton. Pearl S. Buck zooms into one coastal Japanese home in wartime where Dr. Sadao chooses universal human compassion over blind militarism, proving true healing knows no enemy flag.', 'Doshi climate ethic (2.5M) + Buck humanitarian ethic (2.5M)', NULL, 'Tishani Doshi zooms out to 650-million-year geological history, proving human civilisation occupies barely 12 seconds on a planetary clock yet threatens whole food webs via global warming unless youth protect small things like phytoplankton. Pearl S. Buck zooms into one coastal Japanese home in wartime where Dr. Sadao chooses universal human compassion over blind militarism, proving true healing knows no enemy flag.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000056', 'VISTAS EXTRACT (4 × 1M):
(i) What vessel carried Tishani Doshi to Antarctica and how many hours/transports did it take? (ii) What was "Cordilleran folds and pre-Cambrian granite shields"? (iii) Contrast "Akademik Shokalskiy" students with casual tourists. (iv) Meaning of "prognosis" in Antarctica context.', NULL, NULL, 'CASE', 'English Core', 'Vistas: Journey to the End of the Earth & The Enemy', 4, '(i) Russian research vessel Akademik Shokalskiy; over 100 hours via car, aeroplane, and ship across 9 time zones, 6 checkpoints, 3 bodies of water. (ii) Ancient geological belts uniting India, Antarctica, and South America in Gondwana. (iii) Tourists seek pretty selfies; high-schoolers witness melting shelves and change lifelong policy thinking. (iv) Forecast / prediction of Earth''s climate future.', '4 × 1M = 4M', 'Boarding the Russian research vessel Akademik Shokalskiy after 100 hours of travel from sunny Madras across nine time zones, Tishani Doshi stepped onto Antarctica''s blinding white horizon linking Earth''s deepest geological past to its fragile future.', '(i) Russian research vessel Akademik Shokalskiy; over 100 hours via car, aeroplane, and ship across 9 time zones, 6 checkpoints, 3 bodies of water. (ii) Ancient geological belts uniting India, Antarctica, and South America in Gondwana. (iii) Tourists seek pretty selfies; high-schoolers witness melting shelves and change lifelong policy thinking. (iv) Forecast / prediction of Earth''s climate future.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000057', 'What common bond unites lonely old Mr. Lamb and bitter 14-year-old Derry in Susan Hill''s "On the Face of It"?', '{"A":"Both love cricket","B":"Both carry visible physical impairments (Mr. Lamb''s blown-off tin leg; Derry''s acid-scarred face) judged cruelly by society","C":"Both live in cities","D":"Both paint portraits"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 1, 'Mr. Lamb transforms isolation into openness; Derry hides in fear.', NULL, NULL, 'Mr. Lamb transforms isolation into openness; Derry hides in fear.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000058', 'Why did Mr. Lamb deliberately leave his garden gate open and put NO curtains on his windows?', '{"A":"Windows were broken","B":"He hated shutting things in or out — welcoming bees, crab apples, sunlight, and anyone wanting company","C":"Couldn''t afford curtains","D":"Loved cold air"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 1, 'Symbolises total emotional openness against society''s prejudice.', NULL, NULL, 'Symbolises total emotional openness against society''s prejudice.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000059', 'What cruel remark whispered by two women at a bus stop convinced Derry people found his face monstrous?', '{"A":"\"He is lazy\"","B":"\"Look at that, that''s a terrible thing. That''s a face only a mother could love\"","C":"\"He lost his bus\"","D":"\"He looks tired\""}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 1, 'Hurtful pity scarred Derry deeper than the acid itself.', NULL, NULL, 'Hurtful pity scarred Derry deeper than the acid itself.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000005a', 'In Zitkala-Sa''s "The Cutting of My Long Hair", why did she fiercely fight having her thick braids cut at Carlisle Indian School?', '{"A":"Hair was dirty","B":"Among Native Americans, short shingled hair was worn ONLY by mourners and captured cowards — cutting it stripped her cultural dignity","C":"She liked winter warmth","D":"It hurt her eyes"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 1, 'Forced assimilation crushed indigenous identity.', NULL, NULL, 'Forced assimilation crushed indigenous identity.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000005b', 'How did Bama learn about the ugly reality of Untouchability in "We Too Are Human Beings"?', '{"A":"From a textbook","B":"Laughing at a village elder carrying vadais gingerly by a string for the landlord, until brother Annan explained caste humiliation","C":"Newspaper","D":"From her teacher"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 1, 'Childhood amusement turned to righteous indignation and drive to excel.', NULL, NULL, 'Childhood amusement turned to righteous indignation and drive to excel.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000005c', 'What practical weapon did Bama''s elder brother Annan urge her to seize to win dignity against caste prejudice?', '{"A":"Violence","B":"Studying hard with determination and always standing first in class so people would come to her on their own accord","C":"Leaving school","D":"Hiding"}'::jsonb, 'B', 'MCQ', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 1, 'Education transforms dignity and commands respect.', NULL, NULL, 'Education transforms dignity and commands respect.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000005d', 'Explain Mr. Lamb''s parable of "Weeds and Flowers" and "The Man Who Locked Himself Inside a Room".', NULL, NULL, 'VSA', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 2, 'Weeds are also living green growth just like flowers ("Why is one green growing plant called a weed and another flower?"). Locking yourself indoors fearing buses, donkeys, and lightning still risks a picture falling off the wall and killing you — isolation is deadlier than risk.', '1M each', NULL, 'Weeds are also living green growth just like flowers ("Why is one green growing plant called a weed and another flower?"). Locking yourself indoors fearing buses, donkeys, and lightning still risks a picture falling off the wall and killing you — isolation is deadlier than risk.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000005e', 'Why did Derry run back three miles through rain to Mr. Lamb''s garden despite his mother forbidding him?', NULL, NULL, 'VSA', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 2, 'Mr. Lamb had sparked courage in him ("You''ve got two arms, two legs, eyes, ears, brain... you''ll get on better than all the rest"); Derry realised if he didn''t go back now, he would never go anywhere in the world.', 'Self-transformation & courage (2M)', NULL, 'Mr. Lamb had sparked courage in him ("You''ve got two arms, two legs, eyes, ears, brain... you''ll get on better than all the rest"); Derry realised if he didn''t go back now, he would never go anywhere in the world.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000005f', 'VISTAS EXTRACT (4 × 1M):
(i) What tragic ending awaits Derry upon returning to the garden? (ii) Why had Mr. Lamb climbed the ladder alone despite his tin leg? (iii) How did Derry prove Mr. Lamb''s life wasn''t wasted right at the close? (iv) Significance of "Lamey-Lamb" nickname.', NULL, NULL, 'CASE', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 4, '(i) Mr. Lamb fell off the wooden ladder while picking ripe crab apples and lay dead on the grass. (ii) Nobody else showed up ("everyone says they come back, they never do"), so he climbed carefully himself. (iii) Kneeling weeping "I came back", Derry stepped out of his shell permanently. (iv) Kids teased him, yet he didn''t hate them — keeping apples & toffees ready.', '4 × 1M = 4M', 'Context: Defying his mother''s anxious plea, Derry sprinted breathless back through the open garden gate—only to hear a loud crash of branches and find silent Mr. Lamb sprawled beside the fallen ladder.', '(i) Mr. Lamb fell off the wooden ladder while picking ripe crab apples and lay dead on the grass. (ii) Nobody else showed up ("everyone says they come back, they never do"), so he climbed carefully himself. (iii) Kneeling weeping "I came back", Derry stepped out of his shell permanently. (iv) Kids teased him, yet he didn''t hate them — keeping apples & toffees ready.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000060', 'Compare the oppressive childhood humiliations faced by Zitkala-Sa ("land of apples" dining hall & hair cutting) and Bama (village street landlord bundle).', NULL, NULL, 'CASE', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 4, 'Zitkala-Sa faced sudden cultural erasure — stiff shoes, tight clinging dresses, formulaic bell-eating, and cold shears clipping her proud braided hair while tied to a chair. Bama watched a respected elderly man crawl respectfully holding vadais by a string so his touch wouldn''t "pollute" the upper-caste landlord — fueling lifelong resilience through learning.', 'Zitkala-Sa (2M) + Bama (2M)', NULL, 'Zitkala-Sa faced sudden cultural erasure — stiff shoes, tight clinging dresses, formulaic bell-eating, and cold shears clipping her proud braided hair while tied to a chair. Bama watched a respected elderly man crawl respectfully holding vadais by a string so his touch wouldn''t "pollute" the upper-caste landlord — fueling lifelong resilience through learning.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000061', 'Contrast how physical difference (Derry & Mr. Lamb), cultural assimilation (Zitkala-Sa), and caste discrimination (Bama) challenge self-worth — and highlight how courage, education, and inclusive outlook triumph across all three narratives.', NULL, NULL, 'LA', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 5, 'Mr. Lamb teaches Derry that scars only define life if we turn bitter inside like the acid eating our brain; Zitkala-Sa resists until overpowered and remembers her proud spirit in writing; Bama channels brother Annan''s wisdom into academic excellence dismantling prejudice through competence and dignity.', 'Derry/Lamb (2M) + Zitkala-Sa & Bama resilience (3M)', NULL, 'Mr. Lamb teaches Derry that scars only define life if we turn bitter inside like the acid eating our brain; Zitkala-Sa resists until overpowered and remembers her proud spirit in writing; Bama channels brother Annan''s wisdom into academic excellence dismantling prejudice through competence and dignity.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000062', 'VISTAS EXTRACT (4 × 1M):
(i) Who warned Zitkala-Sa that the paleface woman talked about cutting their long heavy hair? (ii) Where did Zitkala-Sa hide desperately? (iii) Why didn''t her mother''s comfort reach her ("not a soul reasoned quietly with me")? (iv) What universal theme unites "Memories of Childhood"?', NULL, NULL, 'CASE', 'English Core', 'Vistas: On the Face of It & Memories of Childhood', 4, '(i) Her friend Judewin, who understood a few words of English. (ii) Crept up stairs into a large dim room with three white beds and squeezed far under the farthest bed in a dark corner. (iii) Forced boarding school treated children coldly like "little animals driven by a herder". (iv) Resistance against marginalisation and preservation of human dignity.', '4 × 1M = 4M', 'Watching helplessly as Judewin sighed "We have to submit, because they are strong," young Zitkala-Sa whispered fiercely "No, I will not submit! I will struggle first!" before slipping unseen up the wooden stairs.', '(i) Her friend Judewin, who understood a few words of English. (ii) Crept up stairs into a large dim room with three white beds and squeezed far under the farthest bed in a dark corner. (iii) Forced boarding school treated children coldly like "little animals driven by a herder". (iv) Resistance against marginalisation and preservation of human dignity.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000063', 'What is the prescribed word limit and mark weightage for CBSE Class 12 Notice Writing or Formal/Informal Invitation & Reply?', '{"A":"150 words, 5 marks","B":"50 words inside a neat box, 4 marks","C":"100 words, 6 marks","D":"25 words, 2 marks"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 1, 'Class 12 Section B short writing tasks carry 4 marks each (50-word box format).', NULL, NULL, 'Class 12 Section B short writing tasks carry 4 marks each (50-word box format).', 'EASY', true),
        ('12051111-0000-4000-8000-000000000064', 'Standard layout sequence of a CBSE School/RWA Notice inside a box is:', '{"A":"Message -> Date -> School Name","B":"Name of Issuing Organisation (CAPS) -> NOTICE -> Date (left) -> Heading -> Body (What, When, Where, Who, Contact) -> Signature, Name & Designation","C":"Salutation -> Body -> Yours truly","D":"Subject -> Date"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 1, '50-word boxed layout with all 5W details.', NULL, NULL, '50-word boxed layout with all 5W details.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000065', 'A Formal Printed Card Invitation (e.g., School Annual Day or Wedding) MUST be written in:', '{"A":"First person (\"I invite you...\")","B":"Third person (\"The Principal, Staff and Students cordially invite you...\") without signature inside card","C":"Slang dialogue","D":"Past tense"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 1, 'Printed card invitations use formal third person, centred symmetry inside a box, RSVP at bottom-left.', NULL, NULL, 'Printed card invitations use formal third person, centred symmetry inside a box, RSVP at bottom-left.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000066', 'When writing a Formal Letter of Reply Accepting or Declining a Personal Formal Invitation, the writer uses:', '{"A":"Boxed card layout","B":"Third person (or first person in formal letter reply to Chief Guest) thanking clearly and confirming/regretting attendance citing exact date/event","C":"Notice format","D":"No date"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 1, 'Formal replies stay crisp within 50 words matching formal register.', NULL, NULL, 'Formal replies stay crisp within 50 words matching formal register.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000067', 'What must ALWAYS appear at the bottom-left of a Formal Card Invitation box?', '{"A":"Price tag","B":"R.S.V.P. (with Host Name & Phone/Contact)","C":"Chief Guest speech","D":"Signature of Printer"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 1, 'RSVP lets hosts track confirmation counts cleanly.', NULL, NULL, 'RSVP lets hosts track confirmation counts cleanly.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000068', 'In an Informal Invitation or Reply to a close friend/cousin (50 words), which tone & pronouns apply?', '{"A":"Strict third person (\"Mrs Verma thanks...\")","B":"Warm first/second person letter layout (\"Dear Rohan... You''ll be thrilled to know...\")","C":"NOTICE heading","D":"No salutation"}'::jsonb, 'B', 'MCQ', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 1, 'Friendly first/second person informal letter format.', NULL, NULL, 'Friendly first/second person informal letter format.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000069', 'List the 5 mandatory "W" details that every 50-word CBSE Notice body must answer clearly.', NULL, NULL, 'VSA', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 2, '1. What is the event/lost item/rule; 2. Who is eligible/invited; 3. When (exact date & time); 4. Where (exact venue); 5. Whom to contact / deadline for names/entries.', '5 clear points (2M)', NULL, '1. What is the event/lost item/rule; 2. Who is eligible/invited; 3. When (exact date & time); 4. Where (exact venue); 5. Whom to contact / deadline for names/entries.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000006a', 'Write the third-person formal card text (40 words) inviting parents to St. Xavier''s School Annual Science Exhibition.', NULL, NULL, 'VSA', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 2, 'THE PRINCIPAL, STAFF & STUDENTS of ST. XAVIER''S SCHOOL, BHOPAL cordially invite you to ANNUAL SCIENCE EXHIBITION on Friday, 15 Dec 2026 at 10:00 AM in School Auditorium. Chief Guest: Dr. A. Verma (ISRO). RSVP: Principal (0755-24XXXXXX).', 'Third-person card layout (2M)', NULL, 'THE PRINCIPAL, STAFF & STUDENTS of ST. XAVIER''S SCHOOL, BHOPAL cordially invite you to ANNUAL SCIENCE EXHIBITION on Friday, 15 Dec 2026 at 10:00 AM in School Auditorium. Chief Guest: Dr. A. Verma (ISRO). RSVP: Principal (0755-24XXXXXX).', 'MEDIUM', true),
        ('12051111-0000-4000-8000-00000000006b', 'Write a 50-word NOTICE as Secretary of Greenwoods RWA informing residents about an Emergency Water Supply Shutdown on Sunday from 10 AM to 4 PM due to overhead tank cleaning.', NULL, NULL, 'CASE', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 4, 'Boxed heading GREENWOODS RESIDENTS WELFARE ASSOCIATION -> NOTICE -> Date -> WATER SUPPLY SHUTDOWN -> Clear details (reason, Sunday date, 10 AM–4 PM, request storing adequate water in advance) -> Sign, Rohan Mehta, Secretary.', 'Format & Box (1M) + 5W Content (2M) + Accuracy (1M)', 'RWA Context: Municipal pipeline valve replacement and overhead tank chlorination require a 6-hour daytime water shutdown across Blocks A–D.', 'Boxed heading GREENWOODS RESIDENTS WELFARE ASSOCIATION -> NOTICE -> Date -> WATER SUPPLY SHUTDOWN -> Clear details (reason, Sunday date, 10 AM–4 PM, request storing adequate water in advance) -> Sign, Rohan Mehta, Secretary.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000006c', 'As Dr. Meera Kapoor (Principal, Kendriya Vidyalaya, Jaipur), write a 50-word Formal Reply declining an invitation to act as Chief Judge at the Inter-School Debate Competition at Sunrise Academy due to pre-scheduled CBSE Board practical inspection.', NULL, NULL, 'CASE', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 4, 'Box/Formal letter reply in third person (or crisp formal reply) -> Dr. Meera Kapoor sincerely thanks Principal, Sunrise Academy for the kind invitation on [date/time], but regrets her inability to attend due to prior CBSE practical inspection schedule. Best wishes for grand success.', 'Format (1M) + Polite decline & reason (2M) + Register (1M)', 'Context: Clashing CBSE practical duty dates require a gracious formal refusal within 50 words.', 'Box/Formal letter reply in third person (or crisp formal reply) -> Dr. Meera Kapoor sincerely thanks Principal, Sunrise Academy for the kind invitation on [date/time], but regrets her inability to attend due to prior CBSE practical inspection schedule. Best wishes for grand success.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000006d', 'Draft a 50-word NOTICE as Literary Club President of Modern Public School, Pune inviting Class XI–XII entries for an Inter-House Poetry Recitation & Slam Competition.', NULL, NULL, 'CASE', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 4, 'Boxed MODERN PUBLIC SCHOOL, PUNE -> NOTICE -> Date -> INTER-HOUSE POETRY RECITATION -> Eligibility (XI–XII), Date, Time, Auditorium venue, 3-minute theme limit, submit names to undersigned by deadline -> Signature/Name/President, Literary Club.', 'Format (1M) + Complete details (2M) + Accuracy (1M)', 'School Context: Annual Literary Week opens entries for senior secondary poetry performers.', 'Boxed MODERN PUBLIC SCHOOL, PUNE -> NOTICE -> Date -> INTER-HOUSE POETRY RECITATION -> Eligibility (XI–XII), Date, Time, Auditorium venue, 3-minute theme limit, submit names to undersigned by deadline -> Signature/Name/President, Literary Club.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000006e', 'Draft BOTH Invitation & Acceptance cleanly: (a) A Formal Card Invitation (50 words) on behalf of Mr. & Mrs. Sethi for their daughter Ananya''s Golden Jubilee Alumni / Graduation Dinner (2.5M), AND (b) An Informal Reply (50 words) from Ananya''s cousin Kabir happily accepting the dinner invite (2.5M).', NULL, NULL, 'LA', 'English Core', 'Short Creative Writing (Notices & Invitations/Replies)', 5, '(a) Boxed third-person formal card with host names, event, date, time, hotel venue, RSVP. (b) Warm first-person informal letter reply ("Dear Uncle & Auntie / Ananya... Thrilled to accept... See you at 7:30 PM... Yours lovingly, Kabir").', '(a) 2.5M + (b) 2.5M', NULL, '(a) Boxed third-person formal card with host names, event, date, time, hotel venue, RSVP. (b) Warm first-person informal letter reply ("Dear Uncle & Auntie / Ananya... Thrilled to accept... See you at 7:30 PM... Yours lovingly, Kabir").', 'HARD', true),
        ('12051111-0000-4000-8000-00000000006f', 'What is the prescribed word limit and mark weightage for CBSE Class 12 Section B Long Writing tasks (Job Application/Letter to Editor & Report/Article)?', '{"A":"50 words, 4 marks","B":"120–150 words, 5 marks","C":"300 words, 8 marks","D":"80 words, 3 marks"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 1, 'Class 12 has 2 × 5M long writing questions (120–150 words each).', NULL, NULL, 'Class 12 has 2 × 5M long writing questions (120–150 words each).', 'EASY', true),
        ('12051111-0000-4000-8000-000000000070', 'A complete CBSE Job Application consists of TWO essential parts:', '{"A":"Only a resume","B":"Cover Letter (formal application responding to advertisement) + Separate structured Bio-Data / Curriculum Vitae enclosed below","C":"Only notice","D":"Informal note"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 1, 'Cover letter + tidy tabular Bio-Data (with 2 references at bottom) scores full marks.', NULL, NULL, 'Cover letter + tidy tabular Bio-Data (with 2 references at bottom) scores full marks.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000071', 'Which opening distinguishes a Newspaper Report from an Essay/Article?', '{"A":"Once upon a time...","B":"Byline (Name, Designation) + Dateline (City, Date: Action-packed summary Lead paragraph answering Who/What/When/Where in past tense)","C":"Sir/Madam","D":"Yours faithfully"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 1, 'Reports carry Title, Byline, Dateline, and past-tense objective reporting.', NULL, NULL, 'Reports carry Title, Byline, Dateline, and past-tense objective reporting.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000072', 'In an Article for a School Magazine or Newspaper, the tone is:', '{"A":"Purely tabular","B":"Engaging, reflective, structured across 3–4 paragraphs (Heading + Byline -> Problem/Analysis -> Solutions/Conclusion) in present/universal tense","C":"Notice style","D":"Memo"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 1, 'Heading + Byline -> Intro, Causes/Impacts, Way Forward.', NULL, NULL, 'Heading + Byline -> Intro, Causes/Impacts, Way Forward.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000073', 'In a Job Bio-Data Educational Qualifications table, exams are best ordered:', '{"A":"Randomly","B":"Chronologically (Class X, XII, Graduation, Post-Graduation/B.Ed.) with Board/University, Year, Percentage","C":"Without grades","D":"Alphabetically"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 1, 'Clean chronological table helps recruiters verify eligibility instantly.', NULL, NULL, 'Clean chronological table helps recruiters verify eligibility instantly.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000074', 'Which tense dominates a School Event Report vs an Article on "Digital Privacy"?', '{"A":"Future vs Past","B":"Past tense (event already occurred) vs Present/Modal general tense","C":"Both future","D":"Both past"}'::jsonb, 'B', 'MCQ', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 1, 'Reports document completed events in past tense.', NULL, NULL, 'Reports document completed events in past tense.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000075', 'Write the crisp Heading, Byline, and 35-word Dateline Lead paragraph for a Newspaper Report on a Flood Relief Camp set up by NCC cadets.', NULL, NULL, 'VSA', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 2, 'NCC CADETS SPEARHEAD FLOOD RELIEF CAMP
