-- V481: Seed 126 Class 12 English Core Mock Tests (104 Real-Format 80M Papers + 22 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class_id UUID;
BEGIN
    SELECT id INTO v_class_id FROM learn_exam_types WHERE slug IN ('class-12', 'cbse-class-12') LIMIT 1;
    IF v_class_id IS NULL THEN
        SELECT id INTO v_class_id FROM learn_exam_types WHERE name ILIKE '%Class 12%' LIMIT 1;
    END IF;

    IF v_class_id IS NOT NULL THEN
        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '12050000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '12050000-%';

        ON CONFLICT (id) DO NOTHING;

By Riya Sen, Staff Correspondent
Patna, 27 November 2026: Over 150 senior NCC cadets set up an emergency medical and food distribution camp in flood-hit Danapur yesterday, evacuating 300 stranded families and supplying clean water packets.', 'Headline + Byline (1M) + Dateline Lead 4Ws (1M)', NULL, 'NCC CADETS SPEARHEAD FLOOD RELIEF CAMP
By Riya Sen, Staff Correspondent
Patna, 27 November 2026: Over 150 senior NCC cadets set up an emergency medical and food distribution camp in flood-hit Danapur yesterday, evacuating 300 stranded families and supplying clean water packets.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000076', 'List the 5 compulsory sections inside a Class 12 Bio-Data attached to a Job Application.', NULL, NULL, 'VSA', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 2, '1. Personal Profile (Name, Father''s Name, DOB, Address, Contact/Email), 2. Educational Qualifications (Table), 3. Work Experience, 4. Skills/Languages/Achievements, 5. Two References + Declaration/Sign.', '5 clear sections (2M)', NULL, '1. Personal Profile (Name, Father''s Name, DOB, Address, Contact/Email), 2. Educational Qualifications (Table), 3. Work Experience, 4. Skills/Languages/Achievements, 5. Two References + Declaration/Sign.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000077', 'JOB APPLICATION WITH BIO-DATA (5M, 120–150 words):
You are Rohan/Ritika Sharma of 14, Civil Lines, Agra. Draft an application responding to an advertisement in The Hindustan Times for the post of "Junior Software Engineer" at TechNova Solutions, Noida, enclosing your complete Bio-Data.', NULL, NULL, 'LA', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 5, 'Part 1: Complete formal Cover Letter citing newspaper ad date, B.Tech (CS) + Python/React proficiency, enclosing resume -> Part 2: Tabular Bio-Data (DOB, Contact, Class 10/12/B.Tech table, 1-yr internship experience, technical skills, hobbies, 2 professional references).', 'Format & Cover Letter (2.5M) + Structured Bio-Data (2.5M)', NULL, 'Part 1: Complete formal Cover Letter citing newspaper ad date, B.Tech (CS) + Python/React proficiency, enclosing resume -> Part 2: Tabular Bio-Data (DOB, Contact, Class 10/12/B.Tech table, 1-yr internship experience, technical skills, hobbies, 2 professional references).', 'HARD', true),
        ('12051111-0000-4000-8000-000000000078', 'LETTER TO THE EDITOR (5M, 120–150 words):
Write a letter to the Editor of The Hindu highlighting the alarming rise of reckless e-scooter/two-wheeler speeding by underage riders without helmets near school zones, suggesting strict traffic-police and parent accountability.', NULL, NULL, 'LA', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 5, 'Formal CBSE layout -> Express civic concern ("Through the columns of your esteemed daily...") -> Detail daily hazard at school dispersal hours -> Suggest CCTV speed cameras, parent-linked challans, and mandatory school safety drives -> Polite urgent closing.', 'Format (1M) + Content & Solutions (2M) + Accuracy & Expression (2M)', NULL, 'Formal CBSE layout -> Express civic concern ("Through the columns of your esteemed daily...") -> Detail daily hazard at school dispersal hours -> Suggest CCTV speed cameras, parent-linked challans, and mandatory school safety drives -> Polite urgent closing.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000079', 'NEWSPAPER/MAGAZINE REPORT (5M, 120–150 words):
As Cultural Secretary of Greenwood Public School, Bengaluru, write a report for your school magazine on the "Annual Green Tech & Sustainability Conclave" held in your school auditorium last week.', NULL, NULL, 'LA', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 5, 'Heading + Byline -> Dateline -> Lead paragraph (Inauguration by environmental scientist, 20 participating schools) -> Body (Solar prototypes, plastic-free workshops, student innovation awards) -> Concluding Principal vote of thanks.', 'Format (1M) + Event details in Past Tense (2M) + Cohesion & Expression (2M)', NULL, 'Heading + Byline -> Dateline -> Lead paragraph (Inauguration by environmental scientist, 20 participating schools) -> Body (Solar prototypes, plastic-free workshops, student innovation awards) -> Concluding Principal vote of thanks.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000007a', 'ARTICLE WRITING (5M, 120–150 words):
Write an engaging article on "The Dual Edge of Generative AI in Student Learning: Tool or Crutch?" emphasising critical thinking, fact-checking, and ethical academic honesty.', NULL, NULL, 'LA', 'English Core', 'Long Creative Writing (Job Application, Letters, Reports & Articles)', 5, 'Catchy Title + Byline -> Opening hook on instant AI answers -> Balanced analysis (personalised brainstorming/doubt-clearing vs plagiarism, hallucinated facts, and shallow thinking) -> Call for verified ethical use -> Memorable closing.', 'Format (1M) + Balanced Content (2M) + Expression & Accuracy (2M)', NULL, 'Catchy Title + Byline -> Opening hook on instant AI answers -> Balanced analysis (personalised brainstorming/doubt-clearing vs plagiarism, hallucinated facts, and shallow thinking) -> Call for verified ethical use -> Memorable closing.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000007b', 'In Class 12 Section A Reading (22 Marks: 12M Discursive + 10M Case-Based Factual), Assertion-Reasoning reading items require:', '{"A":"Outside knowledge","B":"Verifying strictly whether BOTH A and R appear explicitly/logically in the passage and whether R causes A","C":"Guessing","D":"Picking longest line"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 1, 'Never extrapolate outside passage facts.', NULL, NULL, 'Never extrapolate outside passage facts.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000007c', 'When a reading question asks "Complete the analogy from Paragraph 2: Desert : Oasis :: _____ : Wetland", you must:', '{"A":"Guess a city","B":"Match the exact grammatical and semantic relationship using words inside Paragraph 2","C":"Write an essay","D":"Change tense"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 1, 'Preserve exact conceptual pair & part of speech.', NULL, NULL, 'Preserve exact conceptual pair & part of speech.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000007d', 'Why are Open-Ended Short Answer Reading questions (2 marks each, ~40 words) scored strictly on concise precision?', '{"A":"Word count bonus","B":"CBSE rubrics award 1M per distinct passage point, penalising blind multi-line copy-pasting without answering the \"how/why\"","C":"Font style","D":"Spelling only"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 1, 'Paraphrase/synthesise exact two points cleanly in ~30–40 words.', NULL, NULL, 'Paraphrase/synthesise exact two points cleanly in ~30–40 words.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000007e', 'In a Case-Based Factual passage pairing text with a survey bar-graph, "disparity" refers to:', '{"A":"Agreement","B":"A noticeable gap or inequality between two groups/figures","C":"Total sum","D":"Similarity"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 1, 'Important analytical vocabulary term.', NULL, NULL, 'Important analytical vocabulary term.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000007f', 'Tone word "cautionary yet optimistic" indicates the author:', '{"A":"Is purely angry","B":"Warns seriously of risks/hazards while expressing confidence that human action/solutions can succeed","C":"Mocks everyone","D":"Uses sarcasm"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 1, 'Recognising balanced tone avoids extreme options.', NULL, NULL, 'Recognising balanced tone avoids extreme options.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000080', 'What distinguishes a factual statement from an opinion in Section A critical reading?', '{"A":"Length","B":"Factual statements are objectively verifiable with data/events; opinions express subjective judgment or belief","C":"Italic font","D":"Paragraph number"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 1, 'Frequent CBSE Class 12 MCQs test Fact vs Opinion.', NULL, NULL, 'Frequent CBSE Class 12 MCQs test Fact vs Opinion.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000081', 'Read & Answer (2M, ~40 words): "Silent walking — strolling for 20 minutes without podcasts, notifications, or music — restores prefrontal attention fatigue caused by relentless digital multitasking." — Explain WHY notification-free walking helps busy students according to the excerpt.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 2, 'Removing constant digital audio/notification inputs gives an overworked prefrontal cortex rest from multitasking, effectively repairing mental attention fatigue within twenty minutes.', 'Mental rest from multitasking + Restoring attention fatigue (2M)', NULL, 'Removing constant digital audio/notification inputs gives an overworked prefrontal cortex rest from multitasking, effectively repairing mental attention fatigue within twenty minutes.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000082', 'Read & Answer (2M, ~40 words): "Agrivoltaics pairs elevated solar panels directly above shade-tolerant crops like spinach and tomatoes; panels cool slightly from plant transpiration while shading prevents crop scorching." — Describe the mutual benefit between crops and solar panels.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 2, 'Plant transpiration cools elevated solar panels improving electricity efficiency, while panel shade protects crops from excessive heat scorching and lowers soil evaporation.', '1M panel benefit + 1M crop benefit', NULL, 'Plant transpiration cools elevated solar panels improving electricity efficiency, while panel shade protects crops from excessive heat scorching and lowers soil evaporation.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000083', 'Read & Answer (2M, ~40 words): "While electric two-wheelers cut tailpipe smog immediately, battery sustainability depends on ethical lithium recovery and decarbonising the coal-heavy electricity grid charging them." — State two conditions determining true green impact of EVs.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 2, 'True lifecycle emission reduction requires: (1) sustainable/ethical battery recycling and lithium recovery, and (2) shifting power charging grids away from coal toward clean renewables.', '1M × 2', NULL, 'True lifecycle emission reduction requires: (1) sustainable/ethical battery recycling and lithium recovery, and (2) shifting power charging grids away from coal toward clean renewables.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000084', '(i) Compare single-crop monoculture lawns vs urban micro-forests ("Miyawaki"). (ii) Why do Miyawaki native groves grow nearly 10× faster in early years? (iii) Mention two urban benefits beyond shade. (iv) Pick a word from the excerpt meaning "tightly crowded/compact".', NULL, NULL, 'CASE', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 4, '(i) Monoculture lawns need heavy watering/mowing with near-zero biodiversity; Miyawaki packs dense multi-layered native saplings becoming self-sustaining in 3 years. (ii) Close root competition for sunlight accelerates upward vertical growth while rich soil mulch holds moisture. (iii) Absorbing storm run-off & cooling local microclimates / sheltering birds. (iv) Dense.', '4 × 1M = 4M', 'Dense Miyawaki Micro-Forests: Unlike thirsty monoculture grass lawns requiring constant mowing, Miyawaki urban micro-forests plant 3–4 native saplings per square metre across four canopy layers. Intense early competition drives trees upward nearly ten times faster, turning tiny empty traffic islands into self-sustaining cool bird-sanctuaries within three years.', '(i) Monoculture lawns need heavy watering/mowing with near-zero biodiversity; Miyawaki packs dense multi-layered native saplings becoming self-sustaining in 3 years. (ii) Close root competition for sunlight accelerates upward vertical growth while rich soil mulch holds moisture. (iii) Absorbing storm run-off & cooling local microclimates / sheltering birds. (iv) Dense.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000085', 'Discursive Reading Synthesis (5M):
(a) Explain why "deep reading" of long printed books differs cognitively from "skimming" short feeds (2M).
(b) State two practical habits psychologists recommend to rebuild deep focus (2M).
(c) Give an antonym of "fleeting" from the excerpt (1M).', NULL, NULL, 'LA', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 5, '(a) Deep print reading trains sustained linear patience, empathetic imagination, and complex inferential reasoning, whereas rapid screen skimming conditions the brain to crave fleeting novelty and fragmented headlines. (b) Scheduling 25-minute phone-free paper reading blocks and summarising complex chapters by hand. (c) Sustained.', '(a) 2M + (b) 2M + (c) 1M', 'Neuroscience studies reveal that sustained long-form reading wires neural circuits for patience, critical inference, and deep empathy. Conversely, frantic digital skimming across fleeting notifications trains the brain to scan impatiently for quick dopamine hits unless readers intentionally carve out quiet device-free paper reading sessions.', '(a) Deep print reading trains sustained linear patience, empathetic imagination, and complex inferential reasoning, whereas rapid screen skimming conditions the brain to crave fleeting novelty and fragmented headlines. (b) Scheduling 25-minute phone-free paper reading blocks and summarising complex chapters by hand. (c) Sustained.', 'HARD', true),
        ('12051111-0000-4000-8000-000000000086', 'READING CASE-BASED EXTRACT TEST (6 × 1M):
(i) Percentage drop in food-waste methane when composted rather than landfilled (~75%+? -> answer from passage: "eliminates nearly 80% of landfill methane"). (ii) What happens when organic kitchen waste rots buried under plastic in dumps? (iii) Name two valuable outputs from modern municipal biogas digesters. (iv) Why is household source-segregation non-negotiable? (v) Word meaning "lacking oxygen". (vi) Suitable concise title.', NULL, NULL, 'CASE', 'English Core', 'Reading Comprehension (Unseen Discursive & Case-Based)', 6, '(i) Eliminates nearly 80% of landfill methane emissions. (ii) Deprived of oxygen (anaerobic burial), rotting food generates potent heat-trapping methane gas instead of harmless CO₂/compost. (iii) Clean cooking/electricity biogas + nutrient-rich organic farm compost. (iv) Contaminated mixed plastics ruin shredders and spoil compost quality. (v) Anaerobic. (vi) "Turning Kitchen Waste into Clean Energy".', '6 × 1M = 6M', 'Buried beneath non-biodegradable plastics inside overflowing landfills, discarded vegetable peels rot under anaerobic conditions, releasing potent methane gas that accelerates climate warming. Municipalities adopting household source-segregation and enclosed biogas digesters eliminate nearly 80% of landfill methane while converting clean organic scrap into cooking fuel and rich farm compost.', '(i) Eliminates nearly 80% of landfill methane emissions. (ii) Deprived of oxygen (anaerobic burial), rotting food generates potent heat-trapping methane gas instead of harmless CO₂/compost. (iii) Clean cooking/electricity biogas + nutrient-rich organic farm compost. (iv) Contaminated mixed plastics ruin shredders and spoil compost quality. (v) Anaerobic. (vi) "Turning Kitchen Waste into Clean Energy".', 'HARD', true),
        ('12051111-0000-4000-8000-000000000087', '[Passage 1: "Precision Irrigation and Soil Moisture Telemetry"]
Over 70% of freshwater withdrawn globally goes into agriculture, yet traditional flood irrigation wastes nearly half through surface evaporation and deep percolation. Precision drip irrigation coupled with buried capacitive moisture sensors offers a transformative remedy. Instead of watering fixed calendar schedules, sensors transmit real-time root-zone tension readings to low-power microcontrollers that open solenoid valves only when moisture drops below crop-specific thresholds. Field trials across semi-arid Nashik vineyards and Gujarat cotton belts showed water consumption plummeted by 42% while fertiliser efficiency improved because soluble nutrients were delivered directly to active roots (fertigation), boosting marketable yields by 18%.

Why does traditional flood irrigation waste nearly half of applied agricultural water?', '{"A":"Crops drink too slowly","B":"Through surface evaporation and deep percolation beyond roots","C":"Valves leak continuously","D":"Rain washes sensors away"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Surface evaporation and deep percolation account for nearly half the water lost in flood irrigation.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000088', '[From "Precision Irrigation and Soil Moisture Telemetry"] What percentage of global freshwater withdrawal is used by agriculture?', '{"A":"18%","B":"42%","C":"Over 70%","D":"95%"}'::jsonb, 'C', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (C) is correct. Over 70% of freshwater withdrawn globally goes into agriculture.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000089', '[From "Precision Irrigation and Soil Moisture Telemetry"] What does "fertigation" refer to in the passage?', '{"A":"Spraying pesticides from drones","B":"Delivering soluble nutrients directly to active roots via drip water","C":"Rotating seasonal crops","D":"Ploughing soil deeper"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Fertigation delivers soluble nutrients directly to active roots through drip irrigation.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000008a', '[From "Precision Irrigation and Soil Moisture Telemetry"] By how much did field trials reduce water use in Nashik and Gujarat?', '{"A":"18%","B":"42%","C":"50%","D":"70%"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Water consumption plummeted by 42% while yields rose 18%.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000008b', '[From "Precision Irrigation and Soil Moisture Telemetry"] Which word in the passage means "fallen or dropped sharply"?', '{"A":"Coupled","B":"Plummeted","C":"Boosted","D":"Percolated"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. "Plummeted" means dropped steeply.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000008c', '[From "Precision Irrigation and Soil Moisture Telemetry"] What triggers the solenoid valves to open in precision drip systems?', '{"A":"Fixed weekly calendar timers","B":"Root-zone moisture falling below crop-specific thresholds","C":"Afternoon sunlight","D":"Fertilizer price drops"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Microcontrollers open valves only when sensor readings fall below crop moisture thresholds.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000008d', '[From "Precision Irrigation and Soil Moisture Telemetry"] How did marketable crop yields change during the field trials?', '{"A":"Declined by 18%","B":"Stayed constant","C":"Increased by 18%","D":"Doubled"}'::jsonb, 'C', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (C) is correct. Marketable yields boosted by 18%.', 'Option (C) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000008e', '[From "Precision Irrigation and Soil Moisture Telemetry"] What device measures moisture inside the root zone?', '{"A":"Capacitive moisture sensors","B":"Wind turbines","C":"Barometers","D":"Rain gauges"}'::jsonb, 'A', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (A) is correct. Buried capacitive moisture sensors measure root-zone moisture tension.', 'Option (A) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-00000000008f', '[From "Precision Irrigation and Soil Moisture Telemetry"] Explain in 30–40 words how automated precision irrigation improves upon calendar-based watering.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'Automated systems monitor real-time root-zone moisture via sensors and irrigate only when needed, preventing both over-watering waste and crop stress while simultaneously delivering exact nutrients directly to roots.', 'Accurate analytical points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase crisply within 40 words. | Common Pitfall: Copying full paragraphs verbatim.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000090', '[From "Precision Irrigation and Soil Moisture Telemetry"] Why is this technology particularly valuable for semi-arid regions like Nashik and Gujarat?', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'By cutting irrigation water consumption by 42% and improving fertiliser efficiency in water-scarce semi-arid belts, farmers safeguard scarce groundwater while raising crop yield and income.', 'Accurate analytical points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase crisply within 40 words. | Common Pitfall: Copying full paragraphs verbatim.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000091', '[Case Passage: "Campus Solar Transition & Zero-Waste Audit (2025)"]
A comparative sustainability audit across 50 CBSE senior secondary schools in 2025 measured energy and waste metrics before and after student-led Eco-Audits. Rooftop solar adoption rose from 22% of schools in 2022 to 68% in 2025, cutting annual electricity bills by an average of ₹4.2 lakh per campus. Composting organic canteen scraps in aerated bins diverted 74% of wet waste from municipal landfills, while eliminating single-use plastic bottles reduced campus plastic litter by 86%.

How many schools participated in the 2025 sustainability audit?', '{"A":"22","B":"50","C":"68","D":"86"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. 50 CBSE senior secondary schools were audited.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify statistics carefully. | Common Pitfall: Mixing percentages.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000092', '[From Audit Data] By how many percentage points did rooftop solar adoption grow between 2022 and 2025?', '{"A":"22 points","B":"46 percentage points (22% -> 68%)","C":"68 points","D":"74 points"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. 68% minus 22% = 46 percentage points.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify statistics carefully. | Common Pitfall: Mixing percentages.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000093', '[From Audit Data] What was the average annual electricity saving per solar-equipped school?', '{"A":"₹74,000","B":"₹4.2 lakh","C":"₹8.6 lakh","D":"₹50 lakh"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. Average savings reached ₹4.2 lakh annually per campus.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify statistics carefully. | Common Pitfall: Mixing percentages.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000094', '[From Audit Data] Which practice diverted 74% of wet waste away from landfills?', '{"A":"Burning canteen scraps","B":"Composting organic scraps in aerated bins","C":"Plastic bottle bans","D":"Installing solar meters"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. Composting in aerated bins diverted 74% of wet waste.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify statistics carefully. | Common Pitfall: Mixing percentages.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000095', '[From Audit Data] Eliminating single-use plastic bottles lowered campus plastic litter by:', '{"A":"42%","B":"68%","C":"74%","D":"86%"}'::jsonb, 'D', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (D) is correct. Campus plastic litter dropped by 86%.', 'Option (D) [1 Mark]', NULL, 'Examiner Tip: Verify statistics carefully. | Common Pitfall: Mixing percentages.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000096', '[From Audit Data] Who led the Eco-Audits highlighted in the report?', '{"A":"Municipal contractors","B":"Student-led teams","C":"External auditors only","D":"Power discoms"}'::jsonb, 'B', 'MCQ', 'English Core', 'Case Reading', 1, 'Option (B) is correct. The report specifically credits student-led Eco-Audits.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Verify statistics carefully. | Common Pitfall: Mixing percentages.', 'EASY', true),
        ('12051111-0000-4000-8000-000000000097', '[From Audit Data] State two measurable environmental and financial gains achieved by audited campuses.', NULL, NULL, 'VSA', 'English Core', 'Case Reading', 2, 'Financially, rooftop solar adoption saved an average of ₹4.2 lakh per campus annually. Environmentally, composting diverted 74% of wet waste from landfills and banning disposable bottles cut plastic litter by 86%.', 'Two clear data-backed insights [2 Marks]', NULL, 'Examiner Tip: Quote percentage figures in support. | Common Pitfall: Omitting concrete figures.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000098', '[From Audit Data] Why are student-led Eco-Audits effective for long-term school sustainability?', NULL, NULL, 'VSA', 'English Core', 'Case Reading', 2, 'Involving students directly in measuring electricity, wet waste, and plastic litter fosters daily accountability and converts environmental policy into practical campus habits.', 'Two clear data-backed insights [2 Marks]', NULL, 'Examiner Tip: Quote percentage figures in support. | Common Pitfall: Omitting concrete figures.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-000000000099', 'You are Rohan/Roshni, Secretary of the Science & Robotics Club at Kendriya Vidyalaya, Pune. Draft a formal notice in 50 words informing Class 11 & 12 students about an Inter-School Science Innovation Hackathon to be held in the school auditorium.', NULL, NULL, 'SA', 'English Core', 'Creative Writing', 4, '┌──────────────────────────────────────────────────┐
       KENDRIYA VIDYALAYA, PUNE
                 NOTICE
27 November 2026

      INTER-SCHOOL SCIENCE INNOVATION HACKATHON
All Class XI and XII students are informed that the Science & Robotics Club is hosting an Inter-School Innovation Hackathon on 10 December 2026 from 9:00 a.m. in the School Auditorium. Teams of three may register working prototype abstracts with the undersigned by 3 December 2026.

Roshni
Secretary, Science & Robotics Club
└──────────────────────────────────────────────────┘', 'Box + Organisation + NOTICE + Date + Heading [1.5 Marks] | All 5 W''s (What, When, Where, Who, Deadline) within 50 words [2.5 Marks]', NULL, 'Examiner Tip: Notice MUST be enclosed in a neat box and adhere strictly to 50 words! | Common Pitfall: Omitting date, venue, or registration deadline.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000009a', 'You are Dr. Meera Nair, an eminent environmental scientist. Draft a formal reply in 50 words accepting the invitation of the Principal, Delhi Public School, Noida, to preside as Chief Guest at their Annual Eco-Symposium on 12 December 2026 at 10:00 a.m.', NULL, NULL, 'SA', 'English Core', 'Creative Writing', 4, '┌──────────────────────────────────────────────────┐
24, Vasant Vihar
New Delhi

27 November 2026

Dr. Meera Nair sincerely thanks the Principal, staff, and students of Delhi Public School, Noida, for their cordial invitation to preside as Chief Guest at the Annual Eco-Symposium on 12 December 2026 at 10:00 a.m. in the School Auditorium.

She has great pleasure in accepting the invitation and looks forward to interacting with the young eco-innovators.
└──────────────────────────────────────────────────┘', 'Box + Third-person formal reply format [1.5 Marks] | Clear acceptance + event date/time/venue restated [2.5 Marks]', NULL, 'Examiner Tip: A formal reply is ALWAYS written in the THIRD PERSON ("Dr. Meera Nair thanks... She has pleasure..."), never "I"! | Common Pitfall: Writing formal reply in first person ("I thank you...") like a casual letter.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000009b', 'You are Vikram/Vidya of 15, Rose Garden, Bengaluru. You saw an advertisement for the post of "Junior Physics Lab Demonstrator" at National Public School, Indiranagar. Write a formal job application with a detailed Bio-Data in 120–150 words.', NULL, NULL, 'LA', 'English Core', 'Creative Writing', 5, '15, Rose Garden
Bengaluru – 560001

27 November 2026

The Principal
National Public School, Indiranagar
Bengaluru

Subject: Application for the post of Junior Physics Lab Demonstrator

Sir/Madam,

In response to your advertisement in The Deccan Herald dated 24 November 2026, I wish to apply for the post of Junior Physics Lab Demonstrator. Having completed B.Sc. (Hons.) Physics with distinction and two years of CBSE laboratory experience, I am well versed in optics, electronics, and CBSE practical assessment protocols. My bio-data is enclosed for your perusal.

Yours faithfully,
Vidya

BIO-DATA
• Name: Vidya Sharma | DOB: 14 May 2001
• Contact: vidya@email.com | 98XXXXXXXX
• Qualifications: B.Sc. (Hons.) Physics (88%, Bengaluru Univ.), B.Ed. (85%)
• Experience: 2 years as Lab Assistant at Greenwood High School
• Skills: Vernier/Optical apparatus calibration, Lab safety management
• References: (1) Dr. R.K. Rao, HOD Physics; (2) Principal, Greenwood High', 'Cover letter format + post reference [2 Marks] | Structured Bio-Data (DOB, qualifications, experience, references) [2 Marks] | Grammar & presentation [1 Mark]', NULL, 'Examiner Tip: Job application ALWAYS consists of two linked parts: short Cover Letter + clean Bio-Data! | Common Pitfall: Writing Bio-Data without a formal cover letter.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000009c', 'You are Aditya/Aditi, Student Correspondent for your school magazine. Write a report in 120–150 words on the "Annual Career & STEM Innovation Fair 2026" organised at your school last Saturday.', NULL, NULL, 'LA', 'English Core', 'Creative Writing', 5, 'ANNUAL CAREER & STEM INNOVATION FAIR DRAWS RECORD RESPONSE
By Aditi, Student Correspondent

New Delhi, 25 November 2026: The Annual Career & STEM Innovation Fair 2026 concluded successfully last Saturday in the Senior Wing Atrium of Kendriya Vidyalaya, witnessing enthusiastic participation from over 600 Class XI–XII students and parents.

Inaugurated at 9:30 a.m. by Dr. Arvind Menon, Senior Scientist at ISRO, the event featured 35 live student prototypes spanning solar microgrids, AI Braille readers, and water-quality sensors. Parallel career counselling sessions covered engineering, medical sciences, design, economics, and emerging green-tech pathways. Interactive Q&A stalls hosted by alumni clarified entrance timelines and scholarship avenues.

The Principal lauded the student coordinators for seamless execution and distributed Best Prototype Certificates at the 4:00 p.m. valedictory ceremony.', 'Headline + Byline + Dateline format [1 Mark] | Past tense factual event coverage (What, Who, Highlights, Outcome) [2.5 Marks] | Objective journalistic tone & accuracy [1.5 Marks]', NULL, 'Examiner Tip: Reports ALWAYS use PAST TENSE and objective third-person journalistic tone with Headline + Byline. | Common Pitfall: Writing in future tense or omitting the Byline.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000009d', 'Read the thematic context of "My Mother at Sixty-Six":
Driving to Cochin airport, the poet notices her sixty-six-year-old mother dozing beside her, her face pale and ashen like a corpse. To shake off that painful fear of losing her mother, the poet looks out at sprinting young trees and merry children, yet at security check she hides her familiar childhood ache behind repeated smiles and "See you soon, Amma."

Answer (6 Marks):
(a) Name the poetic device in "ashen like that of a corpse" and "Trees sprinting". (2M)
(b) Why did the poet deliberately look out at young trees and spilling children? (2M)
(c) What inner fear do the final words "smile and smile and smile" conceal? (2M)', NULL, NULL, 'LA', 'English Core', 'Flamingo Poetry Extract', 6, '(a) "Ashen like that of a corpse" = Simile; "Trees sprinting" = Personification (also imagery of youthful vitality).
(b) The poet turned toward the vibrant, energetic outside world to distract herself from the agonising realisation of her mother''s fragile ageing and approaching mortality.
(c) Her repeated smiles mask the recurring childhood ache of separation and dread that her aged mother might not remain alive when she returns.', '(a) Simile & Personification identified [2 Marks] | (b) Contrast between outer vitality & mother''s frailty [2 Marks] | (c) Concealed fear of permanent separation/death [2 Marks]', NULL, 'Examiner Tip: Notice the poignant contrast between inside the car (silence, pallor, age) and outside (speed, youth, joy). | Common Pitfall: Saying the poet felt happy seeing her mother at the airport.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000009e', 'Read the context of "The Third Level":
Thirty-one-year-old Charley claims to have stumbled onto a non-existent "Third Level" at New York''s Grand Central Station leading back to peaceful 1894 Galesburg. His psychiatrist friend Sam calls it a "waking-dream wish fulfillment" born of modern insecurity—yet Sam himself later disappears to Galesburg and sends Charley a first-day cover dated July 18, 1894!

Answer (4 Marks):
(a) Explain what psychiatrist Sam meant by "waking-dream wish fulfillment". (2M)
(b) What is a "first-day cover", and what twist does Sam''s letter reveal at the story''s end? (2M)', NULL, NULL, 'SA', 'English Core', 'Vistas Prose Extract', 4, '(a) Sam meant Charley''s stress, fear, and insecurity in the post-war modern world made him subconsciously hallucinate an escape to calm pre-war 1894 life.
(b) On the day a new stamp is issued, stamp collectors mail blank envelopes to themselves so the postmark proves the date of issue. Sam''s signed letter inside a July 18, 1894 cover proves Sam himself sought refuge in Galesburg, blurring fantasy and reality.', '(a) Escapist fantasy from modern anxiety [2 Marks] | (b) Definition of first-day cover + ironic twist of Sam escaping too [2 Marks]', NULL, 'Examiner Tip: First-day covers normally hold only blank paper — finding Sam''s written letter inside was the twist! | Common Pitfall: Thinking Charley actually bought 1894 train tickets successfully on his first visit.', 'HARD', true),
        ('12051111-0000-4000-8000-00000000009f', 'Read the context of "The Last Lesson":
Arriving late to school fearing a scolding on participles, young Franz is stunned to find solemn silence, M. Hamel dressed in his green Sunday best, and village elders seated on back benches. M. Hamel announces an order from Berlin banning French in Alsace and Lorraine schools—making today their very last French lesson.

Answer (6 Marks):
(a) Why had village elders like Old Hauser gathered in the back of the classroom? (2M)
(b) Explain what M. Hamel meant by saying "when a people are enslaved, as long as they hold fast to their language it is as if they had the key to their prison." (2M)
(c) Whom did M. Hamel blame (besides students) for the neglect of French learning? (2M)', NULL, NULL, 'LA', 'English Core', 'Flamingo Prose Extract', 6, '(a) To express gratitude for M. Hamel''s 40 years of faithful service, show regret for never attending school seriously, and pay quiet respect to their lost country and mother tongue.
(b) Mother tongue unites a conquered community''s identity, culture, and collective resistance, giving them mental freedom and hope of liberation from Prussian oppression.
(c) He blamed parents (who preferred sending children to farms or mills for extra money) AND himself (for sending students to water his flowers or giving holidays when he wanted to go fishing).', '(a) Gratitude, regret & patriotism of elders [2 Marks] | (b) Language as identity & liberation key [2 Marks] | (c) Shared blame: students, parents & teacher [2 Marks]', NULL, 'Examiner Tip: Highlight "linguistic chauvinism" — imposing one''s language by force. | Common Pitfall: Blaming only Franz and omitting parents/teacher.', 'HARD', true),
        ('12051111-0000-4000-8000-0000000000a0', 'Why did Saheb lose his carefree look after taking up the ₹800 job at the tea stall?', NULL, NULL, 'VSA', 'English Core', 'Flamingo Short Answer', 2, 'As a ragpicker, the plastic bag belonged to Saheb and he was his own master. Carrying the heavy steel canister for the tea-stall owner meant surrendering his freedom and independence even though he earned regular meals and ₹800.', 'Plastic bag (freedom) vs steel canister (loss of independence) [2 Marks]', NULL, 'Examiner Tip: Use the exact contrast: "The steel canister seems heavier than the plastic bag." | Common Pitfall: Saying he earned less money at the tea stall.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a1', 'How did William Douglas finally ensure that not a shred of his old water terror remained after months of swimming training?', NULL, NULL, 'VSA', 'English Core', 'Flamingo Short Answer', 2, 'Unsatisfied with pool laps alone, Douglas swam two miles across Lake Wentworth and swam across Warm Lake and back, confronting tiny returning ripples of fear mid-lake until he conquered residual terror completely.', 'Lake Wentworth & Warm Lake solo swims testing residual fear [2 Marks]', NULL, 'Examiner Tip: Quote Roosevelt''s maxim: "All we have to fear is fear itself." | Common Pitfall: Stopping only at the instructor''s belt-and-pulley drills.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a2', 'Why did the peddler sign his farewell letter to Edla as "Captain von Stahle"?', NULL, NULL, 'VSA', 'English Core', 'Flamingo Short Answer', 2, 'Edla treated the tramp with unconditional dignity and kindness as if he were a real Captain even after discovering his true identity. Her respect awakened his inner nobility, inspiring him to act with a captain''s honour and return the stolen 30 kronor.', 'Elevated to Captain''s dignity by Edla''s compassion [2 Marks]', NULL, 'Examiner Tip: Include exact stolen amount: 30 kronor (three ten-kronor bills). | Common Pitfall: Saying he kept pretending to fool Edla.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a3', 'Why did Gandhiji agree to a 25% refund settlement with British landlords in Champaran instead of insisting on 100%?', NULL, NULL, 'VSA', 'English Core', 'Flamingo Short Answer', 2, 'To Gandhi, the exact cash amount mattered far less than breaking the landlords'' prestige and arrogance. For the first time, British planters were forced to surrender part of their money and dominance, teaching Indian peasants they had rights and defenders.', 'Prestige surrender > money; peasants gain courage & rights [2 Marks]', NULL, 'Examiner Tip: Champaran proved the first triumph of Civil Disobedience in India (1917). | Common Pitfall: Saying Gandhi compromised out of weakness.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a4', 'What is the "exotic moment" Pablo Neruda imagines when everyone keeps still for twelve seconds, and how does stillness differ from "total inactivity"?', NULL, NULL, 'VSA', 'English Core', 'Flamingo Short Answer', 2, 'Keeping still creates a rare "exotic moment" free of rush, engines, and war where humanity unites in quiet introspection. Neruda clarifies stillness is NOT "total inactivity" (death), because Earth itself teaches how apparent winter stillness nurtures hidden life under frost.', 'Exotic unity + contrast stillness vs death/inactivity [2 Marks]', NULL, 'Examiner Tip: Mention "no truck with death" and the Earth winter-spring metaphor. | Common Pitfall: Confusing quiet introspection with laziness or death.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a5', 'How did the hundredth tiger take its final revenge upon the Tiger King?', NULL, NULL, 'VSA', 'English Core', 'Vistas Short Answer', 2, 'Unknown to the Maharaja, his bullet missed the feeble 100th tiger (which merely fainted from shock and was shot by hunters). Later, a tiny sliver from an unpolished wooden toy tiger he bought for his son''s third birthday infected his hand, turning fatal despite surgery.', 'Missed 100th real tiger + fatal infection from wooden toy tiger sliver [2 Marks]', NULL, 'Examiner Tip: Highlight dramatic irony: 99 real tigers spared him, a wooden toy killed him! | Common Pitfall: Saying the 100th live tiger mauled him.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a6', 'Why does Tishani Doshi state that "Take care of the small things and the big things will take care of themselves" in Antarctica?', NULL, NULL, 'VSA', 'English Core', 'Vistas Short Answer', 2, 'Antarctica''s simple ecosystem highlights microscopic phytoplankton that nourish the entire Southern Ocean food chain. Any further ozone depletion harming these tiny organisms disrupts marine life and global carbon cycles—proving small ecological disruptions trigger massive global consequences.', 'Phytoplankton metaphor showing small ecological links sustain global biosphere [2 Marks]', NULL, 'Examiner Tip: Connect phytoplankton + ozone depletion + Gondwana climate lessons. | Common Pitfall: Writing generic study advice without mentioning phytoplankton!', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000a7', 'Freedom from fear and economic exploitation requires both collective courage and practical self-reliance. Discuss with reference to BOTH "Indigo" (Gandhiji at Champaran) AND "Lost Spring" (Mukesh''s dream in Firozabad). (120–150 words)', NULL, NULL, 'LA', 'English Core', 'Flamingo Long Answer', 5, 'Both Louis Fischer''s "Indigo" and Anees Jung''s "Lost Spring" reveal that breaking cycles of generational exploitation demands overcoming paralysing fear through self-reliant action.

In "Indigo", Champaran sharecroppers were crushed under unjust synthetic-indigo contracts and terrified of British courts until Gandhiji stood firm at Motihari. When thousands of peasants rallied around the courthouse, British officials realised their authority was challenged. Beyond legal relief, Gandhi refused C.F. Andrews'' help to teach Indians self-reliance and launched schools, sanitation, and clinics to uplift villagers permanently.

Contrastingly, in "Lost Spring", Firozabad bangle-makers remain trapped by middlemen, moneylenders, and police into believing glass-blowing is their unchangeable "karam". Yet young Mukesh dares to break free—insisting on walking to a distant garage to train as a motor mechanic. Both narratives prove true liberation begins when fear gives way to purposeful determination.', 'Gandhi''s fear-breaking & self-reliance lesson in Indigo [2 Marks] | Mukesh''s quiet rebellion vs Firozabad fatalism in Lost Spring [2 Marks] | Comparative synthesis & fluency [1 Mark]', NULL, 'Examiner Tip: Mention Gandhi declining C.F. Andrews'' support as the direct textual example of self-reliance! | Common Pitfall: Forgetting to contrast Mukesh with his resigned elders.', 'HARD', true),
        ('12051111-0000-4000-8000-0000000000a8', 'True humanity transcends national hostility and physical prejudice. Justify this statement by drawing parallels between Dr. Sadao Hoki in "The Enemy" AND Mr. Lamb in "On the Face of It". (120–150 words)', NULL, NULL, 'LA', 'English Core', 'Vistas Long Answer', 5, 'Both Pearl S. Buck''s "The Enemy" and Susan Hill''s "On the Face of It" portray individuals whose empathy triumphs over deep-rooted social or wartime barriers.

In "The Enemy", during World War II, Japanese surgeon Dr. Sadao discovers a wounded American prisoner of war washed ashore near his home. Despite risking arrest as a traitor and facing his servants'' walkout, Sadao honours his Hippocratic oath—operating skillfully to remove the bullet, nursing the soldier back to health, and finally equipping him with a boat and food to escape safely.

Similarly, in "On the Face of It", young Derry hides behind bitterness due to his acid-scarred face until elderly Mr. Lamb welcomes him into his open garden. Despite having a tin leg and facing children''s mockery ("Lamey-Lamb"), Mr. Lamb teaches Derry to embrace beauty, curiosity, and life without shutting himself away. Both characters affirm that compassion defines true nobility.', 'Dr. Sadao''s medical ethics rising above wartime nationalism [2 Marks] | Mr. Lamb''s open garden & wisdom healing Derry''s alienation [2 Marks] | Thematic link & cohesive expression [1 Mark]', NULL, 'Examiner Tip: Highlight the specific conflicts each overcomes: wartime patriotism vs medical duty; social stigma vs self-acceptance. | Common Pitfall: Retelling full plots without connecting to prejudice/humanity.', 'HARD', true),
        ('12051111-0000-4000-8000-0000000000a9', '[Passage 1: "Neuroplasticity and Lifelong Cognitive Reserve"]
For decades, early neuroscience held that the adult human brain was structurally fixed after adolescence, losing neurons irreversibly with age. Modern neuroimaging has overturned that dogma by demonstrating neuroplasticity—the lifelong capacity of neural networks to reorganise, sprout fresh dendritic connections, and strengthen synaptic pathways in response to novel learning. Bilingual speakers, classical musicians, and adults acquiring complex new skills develop a deeper "cognitive reserve" that cushions the brain against age-related decline. Regular aerobic exercise further stimulates Brain-Derived Neurotrophic Factor (BDNF), a protein often termed "fertiliser for synapses" that supports memory consolidation in the hippocampus.

What earlier belief did modern neuroimaging overturn?', '{"A":"Sleep helps memory","B":"The adult human brain is structurally fixed after adolescence","C":"Exercise boosts heart rate","D":"Bilinguals speak faster"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Early neuroscience believed adult brains were structurally rigid after adolescence.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000aa', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] What is "neuroplasticity" as defined in the passage?', '{"A":"Memory loss due to age","B":"Lifelong capacity of neural networks to reorganise and form new connections","C":"Surgical brain implants","D":"Lack of synaptic pathways"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Neuroplasticity is the brain''s lifelong ability to reorganise and strengthen neural pathways.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000ab', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] Why is BDNF described as "fertiliser for synapses"?', '{"A":"It slows heart rate","B":"It stimulates neural growth and memory consolidation in the hippocampus","C":"It prevents sleep","D":"It only grows in muscles"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. BDNF supports synaptic growth and hippocampal memory consolidation.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000ac', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] Which groups are cited as building strong cognitive reserve?', '{"A":"Passive TV viewers","B":"Bilingual speakers, classical musicians, and lifelong skill learners","C":"People avoiding exercise","D":"Infants only"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Bilinguals, musicians, and adults learning complex skills build deeper cognitive reserve.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000ad', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] Which word in the passage means "an established principle held unquestioningly as truth"?', '{"A":"Reserve","B":"Dogma","C":"Network","D":"Decline"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. "Dogma" refers to an old unquestioned belief later overturned.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000ae', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] Which physical habit boosts natural BDNF production?', '{"A":"Regular aerobic exercise","B":"Fasting indefinitely","C":"Avoiding complex tasks","D":"Sleep deprivation"}'::jsonb, 'A', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (A) is correct. Regular aerobic exercise stimulates BDNF release.', 'Option (A) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000af', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] Which brain region is specifically linked to BDNF-supported memory consolidation?', '{"A":"Cerebellum","B":"Hippocampus","C":"Medulla","D":"Retina"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. BDNF supports memory consolidation in the hippocampus.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000b0', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] What benefit does a deeper "cognitive reserve" provide in later life?', '{"A":"Instant fluency in ten languages","B":"Cushions the brain against age-related decline","C":"Stops ageing completely","D":"Eliminates need for exercise"}'::jsonb, 'B', 'MCQ', 'English Core', 'Reading Comprehension', 1, 'Option (B) is correct. Cognitive reserve cushions the brain against age-related cognitive decline.', 'Option (B) [1 Mark]', NULL, 'Examiner Tip: Check exact passage evidence. | Common Pitfall: Assuming outside knowledge.', 'EASY', true),
        ('12051111-0000-4000-8000-0000000000b1', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] Explain how mental challenges and physical exercise complement each other in brain health.', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'Mental challenges like music or language learning actively rewire and diversify neural pathways (cognitive reserve), while aerobic exercise supplies BDNF protein that biologically nourishes and strengthens those new hippocampal synapses.', 'Accurate analytical points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase crisply within 40 words. | Common Pitfall: Copying full paragraphs verbatim.', 'MEDIUM', true),
        ('12051111-0000-4000-8000-0000000000b2', '[From "Neuroplasticity and Lifelong Cognitive Reserve"] What hopeful implication does neuroplasticity carry for adult learners?', NULL, NULL, 'VSA', 'English Core', 'Reading Comprehension', 2, 'Since neural circuits keep adapting throughout life, adults are never "too old" to master difficult skills, switch careers, or actively protect long-term memory health.', 'Accurate analytical points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase crisply within 40 words. | Common Pitfall: Copying full paragraphs verbatim.', 'MEDIUM', true)
